insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('k-u-k-monachii', 'k. u. k. Monachii', '', '', '', '', 'k. u. k. Monarchie', '[{"kategorie": "kurz für", "text": "\"kaiserlich-königliche Monarchie\" = \"die [[Doppelmonarchie]] Österreich-Ungarn, die von 1867 bis 1918 existierte\""}, {"kategorie": "", "text": "Sie entstand durch den [[Ausgleich]] von 1867, der die [[Habsburgermonarchie]] in zwei weitgehend autonome Teile aufteilte: das [[Kaiserreich]] Österreich und das [[Königreich]] Ungarn"}, {"kategorie": "", "text": "Beide Teile hatten eigene Parlamente und Regierungen, während sie durch den gemeinsamen Monarchen [[Franz]] Joseph I., der sowohl Kaiser von Österreich als auch König von Ungarn war, sowie gemeinsame Außenpolitik, Militär und Finanzen verbunden waren"}, {"kategorie": "", "text": "Die Monarchie endete 1918 nach dem [[Ersten]] Weltkrieg."}]'::jsonb, ''),
  ('kaisareich-oestarreich', 'Kaisareich Östarreich', '', '', '', '', 'Kaiserreich Österreich', '[{"kategorie": "allg.", "text": "\"offizieller Name der [[Habsburgermonarchie]] von 1804 bis 1867\""}, {"kategorie": "", "text": "Das Kaiserreich Österreich wurde von [[Franz]] II. gegründet, nachdem er seine Krone des [[Heiligen]] Römischen Reiches niedergelegt hatte, um den Einfluss Napoleons zu entgehen"}, {"kategorie": "", "text": "Das Kaiserreich umfasste weite Teile Mitteleuropas, darunter das heutige Österreich, Ungarn, Böhmen, Kroatien und weitere Gebiete"}, {"kategorie": "", "text": "Es war ein Vielvölkerstaat, der von einer zentralen Monarchie regiert wurde"}, {"kategorie": "", "text": "1867 wurde es im Rahmen des [[Ausgleichs]] von 1867 in die [[Doppelmonarchie]] Österreich-Ungarn umgewandelt."}]'::jsonb, ''),
  ('koenigreich-ungarn', 'Königreich Ungarn', '', '', '', '', 'Königreich Ungarn', '[{"kategorie": "allg.", "text": "\"historischer Staat in Mittel- und Osteuropa, der vom Mittelalter bis 1918 existierte\""}, {"kategorie": "", "text": "Das Königreich Ungarn war lange Teil der [[Habsburgermonarchie]] und wurde durch den [[Ausgleich]] von 1867 zu einer der beiden gleichberechtigten Hälften der [[Doppelmonarchie]] Österreich-Ungarn"}, {"kategorie": "", "text": "Das Königreich hatte eine eigene Regierung und Verfassung, während es in den Bereichen Außenpolitik, Militär und Finanzen mit Österreich verbunden war"}, {"kategorie": "", "text": "Nach dem [[Ersten]] Weltkrieg und dem Zerfall der [[Habsburgermonarchie]] wurde das Königreich Ungarn aufgelöst und zur Republik erklärt."}]'::jsonb, ''),
  ('austro-faschismus', 'Austro-Faschismus', '', '', '', '', 'Austro-Faschismus', '[{"kategorie": "allg.", "text": "\"autoritäre, antidemokratische Regierungsform in Österreich, die von 1933 bis 1938 bestand\""}, {"kategorie": "", "text": "Der Austro-Faschismus entstand, nachdem die demokratischen Institutionen unter der Führung der konservativen [[Vaterländischen]] Front und der [[Christlichsozialen]] Partei abgeschafft wurden"}, {"kategorie": "", "text": "Der Austrofaschismus war geprägt von der Errichtung eines Einparteienstaates, der Kontrolle durch den autoritären Bundeskanzler Engelbert [[Dollfuß]] und später Kurt [[Schuschnigg]], sowie der Unterdrückung sozialistischer und kommunistischer Kräfte, insbesondere durch den Einsatz paramilitärischer Einheiten wie der [[Heimwehr]]"}, {"kategorie": "", "text": "Die Bewegung wurde durch den [[Bürgerkrieg]] 1934 gefestigt, als die [[Sozialdemokratische]] Arbeiterpartei (SDAP) nach einem bewaffneten Aufstand brutal unterdrückt wurde"}, {"kategorie": "", "text": "Die Maiverfassung von 1934 stellte den ideologischen Rahmen des Austrofaschismus dar, der eine starke Betonung auf Katholizismus, Antikommunismus und Korporatismus legte. Dies führte zu einer [[Ständestaatsverfassung]], in der verschiedene gesellschaftliche Gruppen durch Zwangsorganisationen eingebunden wurden"}, {"kategorie": "", "text": "Die Hauptmerkmale des Austrofaschismus waren: (i) Autoritärer Einparteienstaat; (ii) Katholische, antimarxistische Ideologie; (iii) Korporatistische Wirtschaftsorganisation; (iv) Unterdrückung der politischen Opposition, insbesondere der Sozialdemokratie; sowie (v) Verfassungsänderungen zur Errichtung eines [[Ständestaates]]"}, {"kategorie": "", "text": "Der Austrofaschismus wird oft als österreichische Sonderform des Faschismus bezeichnet, die sowohl in ideologischer als auch in politischer Hinsicht von anderen faschistischen Bewegungen in Europa, wie dem italienischen Faschismus und dem deutschen Nationalsozialismus, abwich."}]'::jsonb, ''),
  ('dreissigjaehriga-kriag', 'Dreissigjähriga Kriag', '', '', '', '', 'Dreißigjähriger Krieg', '[{"kategorie": "allg.", "text": "\"einer der längsten und zerstörerischsten Konflikte in der europäischen Geschichte (1618–1648)\""}, {"kategorie": "", "text": "Er begann als religiöser Krieg zwischen Protestanten und Katholiken im [[Heiligen]] Römischen Reich, ausgelöst durch den [[Prager]] Fenstersturz 1618, entwickelte sich aber rasch zu einem Machtkampf zwischen europäischen Großmächten\""}, {"kategorie": "", "text": "Die Ursachen des Krieges lagen in den Spannungen, die durch die Reformation und die Spaltung des Christentums in Europa entstanden. Die protestantischen Fürsten im Heiligen Römischen Reich forderten mehr religiöse Autonomie, während die katholischen Herrscher, angeführt von der Habsburger Dynastie, versuchten, die katholische Vorherrschaft zu wahren"}, {"kategorie": "", "text": "Der Krieg wurde in vier Hauptphasen unterteilt: (1) Böhmisch-Pfälzischer Krieg (1618–1625 - Beginn des Krieges nach dem [[Prager]] Fenstersturz und dem Aufstand der böhmischen Protestanten gegen die Habsburger Herrschaft); (2) Dänisch-Niedersächsischer Krieg (1625–1629 - der dänische König Christian IV. kämpfte auf protestantischer Seite, wurde aber von den kaiserlichen Truppen unter Wallenstein geschlagen;  (3) Schwedischer Krieg (1630–1635 - Der schwedische König Gustav II. Adolf griff in den Krieg ein und erzielte wichtige Erfolge für die Protestanten, starb jedoch 1632 in der Schlacht bei Lützen);  (4) Französisch-Schwedischer Krieg (1635–1648 - Frankreich, unter Kardinal Richelieu, verbündete sich mit den Schweden gegen die Habsburger, um deren Macht in Europa zu schwächen)"}, {"kategorie": "", "text": "Der Krieg führte zu enormen Verwüstungen, insbesondere in Deutschland, wo viele Gebiete entvölkert und zerstört wurden. Schätzungen zufolge starben bis zu 8 Millionen Menschen, was etwa einem Drittel der deutschen Bevölkerung entsprach"}, {"kategorie": "", "text": "Der Krieg endete mit dem [[Westfälischen]] Frieden 1648, der das Machtgefüge Europas neu ordnete und die Religionsfreiheit im Reich erweiterte."}]'::jsonb, ''),
  ('westfaelischa-friide', 'Westfälischa Friide', '', '', '', '', 'Westfälischer Friede', '[{"kategorie": "allg.", "text": "Friedensvertrag von 1648, durch welchen der [[Dreißigjährige]] Krieg und der Achtzigjährige Krieg zwischen Spanien und den Niederlanden beendet wurde"}, {"kategorie": "", "text": "Er wurde in den Städten Münster und Osnabrück ausgehandelt und gilt als einer der bedeutendsten Friedensverträge der europäischen Geschichte"}, {"kategorie": "", "text": "Der Friede etablierte das Prinzip der staatlichen Souveränität und die politische Landkarte Europas wurde neu geordnet"}, {"kategorie": "", "text": "Zudem führte er zu einer religiösen Toleranzvereinbarung, die Protestanten und Katholiken in den deutschen Gebieten gleichstellte"}, {"kategorie": "", "text": "Dies markierte das Ende der Hegemonie der [[Habsburger]] in Europa und stärkte die Position von Frankreich und Schweden"}, {"kategorie": "", "text": "Der Friedensvertrag enthielt mehrere Vereinbarungen: (i) Anerkennung der Unabhängigkeit der Niederlande und der Schweiz;  (ii) Festlegung des Religionsfriedens: Das Augsburger Prinzip von 1555 wurde bestätigt, wobei Fürsten das Recht behielten, die Religion ihrer Untertanen zu bestimmen, mit mehr Rechten für Protestanten;  (iii) Schwächung der Habsburger und Stärkung der französischen und schwedischen Positionen in Europa."}]'::jsonb, ''),
  ('praga-fenstaschduaz', 'Praga Fenstaschduaz', '', '', '', '', 'Prager Fenstersturz', '[{"kategorie": "allg.", "text": "\"historisches Schlüsselerlebnis vom 23. Mai 1618, das den [[Dreißigjährigen]] Krieg auslöste\""}, {"kategorie": "", "text": "Dabei wurden zwei katholische Statthalter und ihr Sekretär von protestantischen Adeligen aus einem Fenster der Prager Burg geworfen"}, {"kategorie": "", "text": "Der Streit drehte sich um religiöse Spannungen in Böhmen, einem Teil des [[Heiligen]] Römischen Reiches, wo der katholische Habsburger [[Ferdinand]] II. den Protestantismus einschränken wollte"}, {"kategorie": "", "text": "Im [[Heiligen]] Römischen Reich hatte seit Jahrzehnten ein latenter Konflikt zwischen Katholiken und Protestanten geherrscht. Mit dem [[Majestätsbrief]] von 1609 sicherte der protestantische Adel in Böhmen seine Religionsfreiheit"}, {"kategorie": "", "text": "Als [[Ferdinand]] II. 1617 zum König von Böhmen gewählt wurde, wollte er diese Freiheiten einschränken, was zu wachsendem Widerstand führte. Der Fenstersturz war der Höhepunkt dieses Konflikts"}, {"kategorie": "", "text": "Obwohl die Männer den rund 15 Meter tiefen Sturz überlebten, wurde der Vorfall als symbolischer Akt der Rebellion gegen die Habsburger verstanden, welcher in der Folge zu einem umfassenden europäischen Konflikt, den [[Dreißgjährigen]] Krieg, führte."}]'::jsonb, ''),
  ('majestaetsbriaf-von-1609', 'Majestätsbriaf von 1609', '', '', '', '', 'Majestätsbrief von 1609', '[{"kategorie": "allg.", "text": "\"bedeutendes Dokument, das vom böhmischen König [[Rudolf]] II. unterzeichnet wurde, um den Protestanten im Königreich Böhmen Religionsfreiheit zu gewähren\""}, {"kategorie": "", "text": "Dieses Zugeständnis kam zustande, um den religiösen Konflikt zwischen den katholischen Habsburgern und den protestantischen böhmischen Ständen zu entschärfen"}, {"kategorie": "", "text": "Der Majestätsbrief sicherte den böhmischen Ständen das Recht zu, ihre Religion frei auszuüben, eigene Kirchen zu bauen und sich politisch zu organisieren"}, {"kategorie": "", "text": "Der Versuch der Aufhebung dieses Rechts durch den katholischen König [[Ferdinand]] II. führte später zum [[Prager]] Fenstersturz von 1618 und zum Ausbruch des [[Dreißigjährigen]] Krieges."}]'::jsonb, ''),
  ('wiina-kongress', 'Wiina Kongress', '', '', '', '', 'Wiener Kongress', '[{"kategorie": "allg.", "text": "\"internationale Konferenz, die von September 1814 bis Juni 1815 in Wien stattfand und nach dem Sturz Napoleons die politische Ordnung in Europa neu gestalten sollte\""}, {"kategorie": "", "text": "Unter der Leitung des österreichischen Außenministers Fürst Klemens von [[Metternich]] trafen sich Vertreter der Großmächte (Österreich, Preußen, Russland, Großbritannien und Frankreich), um territoriale Fragen zu klären und das Gleichgewicht der Kräfte wiederherzustellen"}, {"kategorie": "", "text": "Der Kongress führte zur Neuordnung Europas, schuf den [[Deutschen]] Bund und legte die Grundlage für fast ein Jahrhundert relativer Stabilität."}]'::jsonb, ''),
  ('lothringa-schdrossn', 'Lothringa Schdrossn', '', '', '', '', 'Lothringerstraße', '[{"kategorie": "allg.", "text": "zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie wurde nach dem Haus Lothringen benannt, einer Adelsfamilie, die mit den Habsburgern verbunden war"}, {"kategorie": "", "text": "Insbesondere erinnert der Name an Franz Stephan von Lothringen, der durch die Heirat mit Maria Theresia die Dynastie Habsburg-Lothringen begründete und Kaiser des [[Heiligen]] Römischen Reiches war"}, {"kategorie": "", "text": "Das Areal gehörte ab dem 16. Jahrhundert zum [[Glacis]]. Im Zuge der Verbauung desselben wurde 1860 am linken Ufer des (damals noch offen fließenden) Wienflusses die Lothringerstraße eröffnet"}, {"kategorie": "", "text": "Sie war ein Bestandteil der zur Entlastung der Ringstraße konzipierten \"Lastenstraße\" und begann bei der (verlängerten) [[Kärntner]] Straße. 1899 gingen im Zuge der [[Wienflussregulierung]] die Häuser Nummer 1-11 an den [[Karlsplatz]] verloren; seither beginnt die Lothringerstraße bei der [[Canovagasse]] (Rückseite des [[Musikvereinsgebäudes]])"}, {"kategorie": "", "text": "Die Straße ist Teil eines gehobenen Viertels und von repräsentativen Gebäuden sowie Hotels und Botschaften gesäumt."}]'::jsonb, ''),
  ('napoleonische-kriag', 'Napoleonische Kriag', '', '', '', '', 'Napoleonische Kriege', '[{"kategorie": "allg.", "text": "\"Reihe von militärischen Konflikten, die von Napoleon Bonaparte geführt wurden, um die Vorherrschaft Frankreichs in Europa zu sichern\""}, {"kategorie": "", "text": "Die Napoleonischen Kriege folgten auf die [[Französische]] Revolution und umfassten Kämpfe gegen verschiedene Koalitionen europäischer Mächte, darunter Großbritannien, Russland, Österreich und Preußen"}, {"kategorie": "", "text": "Zu den wichtigsten Schlachten gehörten Austerlitz (1805), Leipzig (1813) und schließlich Waterloo (1815), wo Napoleon endgültig besiegt wurde"}, {"kategorie": "", "text": "Die Kriege veränderten die geopolitische Landschaft Europas erheblich und führten zur Restauration monarchistischer Strukturen durch den [[Wiener]] Kongress."}]'::jsonb, ''),
  ('deitscha-kriag', 'Deitscha Kriag', '', '', '', '', 'Deutscher Krieg', '[{"kategorie": "allg.", "text": "\"militärischer Konflikt im Jahr 1866 (auch Bruderkrieg genannt) zwischen dem Königreich Preußen und dem [[Kaisertum]] Österreich, der um die Vorherrschaft in den deutschen Staaten geführt wurde\""}, {"kategorie": "", "text": "Der Deutsche Krieg war das Resultat von Spannungen zwischen den beiden Großmächten über die Führung im [[Deutschen]] Bund"}, {"kategorie": "", "text": "Preußen siegte in der entscheidenden [[Schlacht]] von Königgrätz und setzte die Auflösung des [[Deutschen]] Bundes durch"}, {"kategorie": "", "text": "Der Krieg führte zur Gründung des Norddeutschen Bundes unter preußischer Führung und ebnete den Weg zur deutschen Einigung 1871"}, {"kategorie": "", "text": "Österreich wurde nach der Niederlage in der [[Schlacht]] von Königgrätz (Sadowa) aus dem [[Deutschen]] Bund ausgeschlossen. Damit endete seine Vormachtstellung in den deutschen Staaten"}, {"kategorie": "", "text": "Außerdem wurde Ösxterreich gezwungen, Venetien an Italien abzutreten, das an der Seite Preußens und Italiens gegen Österreich gekämpft hatte"}, {"kategorie": "", "text": "Die Niederlage führte zu inneren Reformen, insbesondere zum [[Ausgleich]] von 1867, der zur Gründung der [[Doppelmonarchie]] Österreich-Ungarn führte."}]'::jsonb, ''),
  ('easchda-woeoedkriag', 'Easchda Wöödkriag', '', '', '', '', 'Erster Weltkrieg', '[{"kategorie": "allg.", "text": "\"globaler militärischer Konflikt (1914-1918), der in Europa begann und schließlich auf viele andere Teile der Welt übergriff\""}, {"kategorie": "", "text": "Auslöser war die Ermordung des österreichischen Thronfolgers [[Franz]] Ferdinand in Sarajevo, was zu einer Eskalation zwischen den Großmächten führte"}, {"kategorie": "", "text": "Die Hauptbeteiligten waren die Alliierten (u. a. Großbritannien, Frankreich, Russland, später die USA) und die [[Mittelmächte]] (Deutschland, Österreich-Ungarn, Osmanisches Reich)"}, {"kategorie": "", "text": "Der Krieg führte zu etwa 16 Millionen Toten und endete mit dem Vertrag von Versailles, der Europa politisch und territorial neu ordnete"}, {"kategorie": "", "text": "Nach der Niederlage brach die [[Doppelmonarchie]] Österreich-Ungarn 1918 auseinander. Mehrere neue Nationalstaaten entstanden, darunter Österreich, Ungarn, die Tschechoslowakei und Jugoslawien"}, {"kategorie": "", "text": "Österreich verlor bedeutende Territorien wie Böhmen, Mähren und Galizien und musste im [[Vertrag]] von Saint-Germain 1919 auf den Großteil seiner Gebiete verzichten und sich als kleine Republik neu konstituieren."}]'::jsonb, ''),
  ('zweita-woeoedkriag', 'Zweita Wöödkriag', '', '', '', '', 'Zweiter Weltkrieg', '[{"kategorie": "allg.", "text": "\"globaler Konflikt (1939–1945), der von den [[Achsenmächten]] (darunter Deutschland, Italien und Japan) gegen die Alliierten (u. a. Großbritannien, die Sowjetunion, die USA und China) geführt wurde\""}, {"kategorie": "", "text": "Der Krieg begann mit dem deutschen Überfall auf Polen und weitete sich schnell auf Europa, Asien und Afrika aus"}, {"kategorie": "", "text": "Er endete 1945 mit der Kapitulation Deutschlands im Mai und Japans im September"}, {"kategorie": "", "text": "Der Krieg führte zu etwa 60 Millionen Toten, dem [[Holocaust]], massiven Zerstörungen und weitreichenden geopolitischen Veränderungen, einschließlich der Gründung der Vereinten Nationen"}, {"kategorie": "", "text": "Nach 1945 wurde Österreich von den [[Alliierten]] befreit und bis 1955 in vier [[Besatzungszonen]] aufgeteilt"}, {"kategorie": "", "text": "Mit dem [[Staatsvertrag]] von 1955 erlangte Österreich seine Souveränität zurück und verpflichtete sich zur [[immerwährenden]] Neutralität."}]'::jsonb, ''),
  ('drittes-reich', 'Drittes Reich', '', '', '', '', 'Drittes Reich', '[{"kategorie": "allg.", "text": "\"Zeit der nationalsozialistischen Herrschaft in Deutschland von 1933 bis 1945 unter Adolf Hitler\""}, {"kategorie": "", "text": "Diese Periode war geprägt von einem totalitären Regime, einer rassistischen Ideologie, einer expansiven Kriegsführung und dem [[Holocaust]]"}, {"kategorie": "", "text": "Österreich spielte eine besondere Rolle im Dritten Reich, da es 1938 nach dem sogenannten [[Anschluss]] in das [[Deutsche]] Reich eingegliedert wurde"}, {"kategorie": "", "text": "Viele Österreicher unterstützten den Anschluss und waren aktiv am NS-Regime beteiligt. Gleichzeitig wurden aber auch zahlreiche Österreicher, insbesondere Juden, verfolgt, deportiert und ermordet"}, {"kategorie": "", "text": "Nach dem Krieg wurde Österreich als erstes Opfer der nationalsozialistischen Aggression anerkannt, was zur Wiederherstellung seiner Unabhängigkeit 1955 beitrug"}]'::jsonb, ''),
  ('deitsches-reich', 'Deitsches Reich', '', '', '', '', 'Deutsches Reich', '[{"kategorie": "allg.", "text": "\"historisches Reich, sich auf das Deutschland zwischen 1871 und 1945 bezieht\""}, {"kategorie": "", "text": "Es umfasste drei Hauptphasen: das Kaiserreich (1871–1918), die Weimarer Republik (1919–1933) und das [[Dritte]] Reich unter der Herrschaft der Nationalsozialisten (1933–1945)"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg und dem Fall des [[Dritten]] Reiches existiert der Begriff \"Deutsches Reich\" nicht mehr als offizieller Staatstitel"}, {"kategorie": "", "text": "Stattdessen ist die moderne Staatsbezeichnung seit 1949 \"Bundesrepublik Deutschland\"."}]'::jsonb, ''),
  ('wiina-laundtoog', 'Wiina Laundtoog', '', '', '', '', 'Wiener Landtag', '[{"kategorie": "pol.", "text": "\"gesetzgebendes Organ des Bundeslandes Wien, das gleichzeitig auch eine eigenständige Stadt ist\""}, {"kategorie": "", "text": "Der Wiener Landtag besteht aus den Abgeordneten des [[Wiener]] Gemeinderats, da Wien als Stadt und Bundesland in Personalunion geführt wird"}, {"kategorie": "", "text": "Die Hauptaufgabe des Wiener Landtags ist die Verabschiedung von Landesgesetzen, die ausschließlich für das Gebiet von Wien gelten"}, {"kategorie": "", "text": "Darüber hinaus kontrolliert der Landtag die [[Wiener]] Landesregierung und entscheidet über das Landesbudget"}, {"kategorie": "", "text": "Die Abgeordneten werden in allgemeinen Wahlen für fünf Jahre gewählt."}]'::jsonb, ''),
  ('wiina-laundesregiirung', 'Wiina Laundesregiirung', '', '', '', '', 'Wiener Landesregierung', '[{"kategorie": "pol.", "text": "\"das Exekutivorgan des [[Bundeslandes]] Wien, welche sich aus dem Bürgermeister (gleichzeitig auch Landeshauptmann) und den Stadträten zusammensetzt\""}, {"kategorie": "", "text": "Sie ist für die Umsetzung der vom [[Wiener]] Landtag beschlossenen Gesetze zuständig und übernimmt die Verwaltung der Landesangelegenheiten Wiens"}, {"kategorie": "", "text": "Da Wien sowohl Stadt als auch Bundesland ist, übt die Wiener Landesregierung gleichzeitig Funktionen einer Stadtregierung und einer Landesregierung aus"}, {"kategorie": "", "text": "Der [[Wiener]] Bürgermeister führt die Regierungsgeschäfte und repräsentiert Wien sowohl auf Landes- als auch auf Bundesebene."}]'::jsonb, ''),
  ('oestarreichische-bundesvafossung', 'Östarreichische Bundesvafossung', '', '', '', '', 'Östereichische Bundesverfassung', '[{"kategorie": "", "text": "Sie regelt die Staatsorganisation, die [[Gewaltenteilung]], die Rechte und Pflichten der Bürger sowie die Kompetenzen zwischen [[Bund]] und Ländern"}, {"kategorie": "", "text": "Die österreichische Bundesverfassung trat erstmals im Oktober 1920 in Kraft und wurde unter der Leitung des Rechtsgelehrten [[Hans]] Kelsen ausgearbeitet"}, {"kategorie": "", "text": "Die Bundesverfassung teilt die [[Staatsgewalt]] in [[Legislative]] (gesetzgebende Gewalt), [[Exekutive]] (ausführende Gewalt) und [[Judikative]] (rechtsprechende Gewalt) auf. Die Legislative besteht aus dem [[Nationalrat]] (direkt gewähltes Parlament) und dem [[Bundesrat]] (Vertretung der Bundesländer). Die Exekutive wird vom [[Bundespräsidenten]] und der [[Bundesregierung]] ausgeübt"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, was bedeutet, dass die Verfassung die Kompetenzen zwischen dem Bund und den neun Bundesländern aufteilt. Die Länder haben eigene Verfassungen und Verwaltungen, während bestimmte Kompetenzen (z. B. Außenpolitik, Verteidigung) beim [[Bund]] liegen"}, {"kategorie": "", "text": "Die Bundesverfassung schützt die [[Grundrechte]] der Bürger, wie etwa die Meinungsfreiheit, Glaubensfreiheit und den Schutz der persönlichen Freiheit. Diese Grundrechte bilden die Basis für die [[Rechtsstaatlichkeit]] und [[demokratische]] Ordnung"}, {"kategorie": "", "text": "Die Änderung der Bundesverfassung ist möglich, erfordert jedoch eine Zweidrittelmehrheit im Nationalrat. Bestimmte besonders wichtige Bestimmungen können nur durch eine [[Volksabstimmung]] geändert werden"}, {"kategorie": "", "text": "Die österreichische Bundesverfassung wurde seit 1920 mehrfach reformiert und ergänzt, bleibt jedoch in ihrem Grundprinzip bestehen."}]'::jsonb, ''),
  ('konstituiirende-sitzung', 'Konstituiirende Sitzung', '', '', '', '', 'Konstituierende Sitzung', '[{"kategorie": "pol.", "text": "\"erste Sitzung des [[Nationalrats]] nach einer Nationalratswahl. Sie markiert den Beginn einer neuen [[Legislaturperiode]] und stellt einen wichtigen formellen Schritt im parlamentarischen System dar\""}, {"kategorie": "", "text": "In dieser Sitzung werden zentrale organisatorische Entscheidungen getroffen, die für die Funktionsfähigkeit des [[Parlaments]] während der gesamten Legislaturperiode entscheidend sind"}, {"kategorie": "", "text": "Die konstituierende Sitzung wird von dem dienstältesten Abgeordneten eröffnet. Dies geschieht, bevor der [[Nationalratspräsident]] und seine Stellvertreter gewählt werden, da diese zu diesem Zeitpunkt noch nicht bestimmt sind"}, {"kategorie": "", "text": "Eines der ersten und wichtigsten Elemente der konstituierenden Sitzung ist die Wahl des Nationalratspräsidenten sowie seiner beiden Stellvertreter. Der Nationalratspräsident wird in der Regel aus der stärksten Fraktion gewählt, während die Stellvertreter aus den zweit- und drittstärksten Fraktionen kommen. Diese Personen leiten zukünftig die [[Plenarsitzungen]] und sorgen für den ordnungsgemäßen Ablauf der parlamentarischen Arbeit"}, {"kategorie": "", "text": "In der konstituierenden Sitzung legen alle neu gewählten Abgeordneten des Nationalrats ihren Eid ab. Mit diesem Schritt werden sie offiziell in ihr Amt eingeführt"}, {"kategorie": "", "text": "In der konstituierenden Sitzung wird auch beschlossen, welche parlamentarischen [[Ausschüsse]] eingerichtet werden. Dies ist wichtig, um die kommende Arbeit des Parlaments effektiv zu organisieren"}, {"kategorie": "", "text": "Die konstituierende Sitzung stellt auch die Grundlage für die spätere Bildung der [[Bundesregierung]] dar. Nach den Verhandlungen zwischen den politischen Parteien und der Wahl des Nationalratspräsidenten wird in den kommenden Tagen oder Wochen der [[Bundeskanzler]] vom [[Bundespräsidenten]] ernannt, woraufhin die [[Bundesregierung]] gebildet wird."}]'::jsonb, ''),
  ('parlamentarischa-ausschuss', 'Parlamentarischa Ausschuss', '', '', '', '', 'Parlamentarischer Ausschuss', '[{"kategorie": "", "text": "Fachausschüsse sind für die inhaltliche Ausarbeitung und Bewertung von Gesetzen verantwortlich und spielen eine zentrale Rolle bei der Sicherstellung, dass [[Gesetze]] umfassend diskutiert und analysiert werden"}, {"kategorie": "", "text": "Jeder Fachausschuss ist für ein bestimmtes Themengebiet zuständig, wie z. B. Finanzen, Gesundheit, Bildung oder Verkehr. Die Abgeordneten, die im jeweiligen Ausschuss sitzen, sind in diesem Bereich erfahren oder spezialisiert"}, {"kategorie": "", "text": "Sobald ein [[Gesetzesentwurf]] im Nationalrat eingebracht und in der ersten [[Lesung]] diskutiert wurde, wird der Entwurf an den zuständigen Fachausschuss weitergeleitet. Hier erfolgt die detaillierte Beratung, in der der Entwurf inhaltlich analysiert und gegebenenfalls geändert wird"}, {"kategorie": "", "text": "Während der [[Ausschussberatungen]] können Experten, Interessenvertreter oder Betroffene angehört werden, um zusätzliche Informationen zu erhalten und die Qualität des Gesetzes zu verbessern. Die Fachausschüsse können auch Änderungen vorschlagen oder Gesetze in ihrer ursprünglichen Form zur Annahme empfehlen"}, {"kategorie": "", "text": "Nach Abschluss der Beratungen erstellt der [[Fachausschuss]] einen Bericht, der dem Nationalrat vorgelegt wird. Dieser Bericht enthält die Empfehlungen des Ausschusses, ob der Entwurf angenommen, abgelehnt oder geändert werden soll"}, {"kategorie": "", "text": "Fachausschüsse können sowohl öffentliche als auch nicht-öffentliche Sitzungen abhalten. Bei wichtigen oder kontroversen Themen können öffentliche Anhörungen stattfinden, um die Transparenz zu erhöhen."}]'::jsonb, ''),
  ('wiina-gemeinderood', 'Wiina Gemeinderood', '', '', '', '', 'Wiener Gemeinderat', '[{"kategorie": "pol.", "text": "\"gesetzgebendes Organ der [[Stadt]] Wien, bestehend aus den Abgeordneten, die alle fünf Jahre bei den Wiener Gemeinderatswahlen gewählt werden\""}, {"kategorie": "", "text": "Da Wien eine Besonderheit als Stadt und Bundesland in Personalunion darstellt, fungiert der Gemeinderat gleichzeitig auch als [[Wiener]] Landtag"}, {"kategorie": "", "text": "Die Aufgaben des Gemeinderats umfassen die Gesetzgebung für die Stadt, die Kontrolle der Stadtverwaltung und die Verabschiedung des Budgets"}, {"kategorie": "", "text": "Der Gemeinderat besteht aus 100 Abgeordneten und ist das zentrale politische Gremium Wiens."}]'::jsonb, ''),
  ('wiina-biagamaasta', 'Wiina Biagamaasta', '', '', '', '', 'Wiener Bürgermeister', '[{"kategorie": "pol.", "text": "\"Oberhaupt der [[Stadt]] Wien und gleichzeitig der Landeshauptmann des [[Bundeslandes]] Wien, da Wien eine besondere Stellung als Stadt und Bundesland in Personalunion hat\""}, {"kategorie": "", "text": "Der Bürgermeister ist verantwortlich für die Leitung der Stadtregierung und repräsentiert Wien sowohl auf städtischer als auch auf bundespolitischer Ebene"}, {"kategorie": "", "text": "Er wird vom [[Wiener]] Gemeinderat gewählt und steht der [[Wiener]] Landesregierung und dem [[Wiener]] Stadtsenat vor"}, {"kategorie": "", "text": "Zu den Aufgaben gehören die Umsetzung städtischer Gesetze und die Verwaltung öffentlicher Dienste."}]'::jsonb, ''),
  ('wiina-laundeshauptmaunn', 'Wiina Laundeshauptmaunn', '', '', '', '', 'Wiener Landeshauptmann', '[{"kategorie": "pol.", "text": "\"Oberhaupt des [[Bundeslandes]] Wien, welches die gleichen Aufgaben wie die Landeshauptleute der anderen österreichischen Bundesländer hat\""}, {"kategorie": "", "text": "Da Wien jedoch eine Doppelrolle als Stadt und Bundesland einnimmt, ist der Landeshauptmann gleichzeitig auch der [[Bürgermeister]] der Stadt Wien"}, {"kategorie": "", "text": "In dieser Funktion leitet er sowohl die [[Wiener]] Landesregierung als auch die [[Stadtregierung]] und repräsentiert Wien auf Bundesebene"}, {"kategorie": "", "text": "Der Wiener Landeshauptmann wird vom [[Wiener]] Landtag (der auch [[Gemeinderat]] ist) gewählt."}]'::jsonb, ''),
  ('wiina-schdodtregiirung', 'Wiina Schdodtregiirung', '', '', '', '', 'Wiener Stadtregierung', '[{"kategorie": "pol.", "text": "Exekutivorgan der [[Stadt]] Wien, das sich aus dem [[Wiener]] Bürgermeister (der gleichzeitig [[Landeshauptmann]] ist) und den [[Stadträten]] zusammen"}, {"kategorie": "", "text": "Sie ist verantwortlich für die Verwaltung der Stadt Wien und die Umsetzung der im [[Wiener]] Gemeinderat (der gleichzeitig der [[Wiener]] Landtag ist) beschlossenen Gesetze"}, {"kategorie": "", "text": "Die Stadtregierung kümmert sich um städtische Angelegenheiten wie Stadtplanung, Verkehr, Bildung und Gesundheit"}, {"kategorie": "", "text": "Der [[Wiener]] Bürgermeister leitet die Regierung und vertritt Wien nach außen"}, {"kategorie": "", "text": "Die [[Stadträte]] sind für bestimmte Ressorts, wie Finanzen oder Wohnbau, zuständig."}]'::jsonb, ''),
  ('wiina-schdodtsenat', 'Wiina Schdodtsenat', '', '', '', '', 'Wiener Stadtsenat', '[{"kategorie": "pol.", "text": "\"Gremium der [[Wiener]] Stadtregierung, das sich aus dem [[Wiener]] Bürgermeister und den amtsführenden [[Stadträten]] zusammensetzt\""}, {"kategorie": "", "text": "Es fungiert als Exekutivorgan und kümmert sich um die Verwaltung und die Umsetzung der politischen Entscheidungen des [[Wiener]] Gemeinderats, der auch als [[Wiener]] Landtag fungiert"}, {"kategorie": "", "text": "Der Wiener Bürgermeister leitet den Stadtsenat, und die [[Wiener]] Stadträte sind jeweils für bestimmte Ressorts wie Finanzen, Verkehr oder Bildung zuständig"}, {"kategorie": "", "text": "Der Stadtsenat ist somit für die konkrete Ausführung städtischer Gesetze und Verordnungen verantwortlich."}]'::jsonb, ''),
  ('wiina-schdodtrood', 'Wiina Schdodtrood', '', '', '', '', 'Wiener Stadtrat', '[{"kategorie": "pol.", "text": "\"Mitglied der [[Wiener]] Stadtregierung, das für die Leitung eines bestimmten Ressorts (z. B. Finanzen, Bildung, Verkehr) verantwortlich ist\""}, {"kategorie": "", "text": "Die Stadträte sind Teil des [[Wiener]] Stadtsenats und werden vom [[Wiener]] Gemeinderat gewählt"}, {"kategorie": "", "text": "Es gibt zwei Arten von Stadträten: amtsführende Stadträte, die direkt für die Verwaltung eines Ressorts zuständig sind, und nicht amtsführende Stadträte, die dem Stadtsenat angehören, aber keine Ressorts leiten"}, {"kategorie": "", "text": "Die Stadträte unterstützen die Umsetzung der politischen Entscheidungen und Gesetze, die derà Wiener Gemeinderat beschließt."}]'::jsonb, ''),
  ('schdodt-wiin', 'Schdodt Wiin', '', '', '', '', 'Stadt Wien', '[{"kategorie": "allg.", "text": "\"Hauptstadt Österreichs und eines der neun [[Bundesländer]] des Landes\""}, {"kategorie": "", "text": "Sie liegt im Osten Österreichs an der [[Donau]] und ist mit rund 2,1 Millionen Einwohnern die bevölkerungsreichste Stadt des Landes"}, {"kategorie": "", "text": "Wien ist ein wichtiges kulturelles, wirtschaftliches und politisches Zentrum in Europa. Die Stadt ist für ihre reiche Geschichte, Architektur und Musiktradition bekannt, darunter weltberühmte Institutionen wie die [[Wiener]] Staatsoper und das [[Schloss]] Schönbrunn"}, {"kategorie": "", "text": "Die Ursprünge Wiens reichen bis zur Römerzeit zurück, als die Stadt als Militärlager namens [[Vindobona]] gegründet wurde"}, {"kategorie": "", "text": "Über die Jahrhunderte entwickelte sich Wien zu einer Residenzstadt der [[Habsburger]] und wurde zum Zentrum des [[Heiligen]] Römischen Reiches und später der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Wien war das Herzstück des kaiserlichen Österreichs und spielte eine zentrale Rolle in Kunst, Musik, Architektur und Philosophie. Die Stadt beherbergt zahlreiche UNESCO-Weltkulturerbestätten wie das historische Zentrum und das [[Schloss]] Schönbrunn"}, {"kategorie": "", "text": "Wien ist zudem ein wichtiger internationaler Knotenpunkt und Sitz vieler internationaler Organisationen wie der Vereinten Nationen (UN) und der Organisation erdölexportierender Länder (OPEC). Die Stadt ist wirtschaftlich stark und bietet eine hohe Lebensqualität, was sie regelmäßig zu einem der besten Wohnorte weltweit macht"}, {"kategorie": "", "text": "Als Hauptstadt ist Wien der Sitz der österreichischen Bundesregierung, des Bundespräsidenten und zahlreicher Ministerien. Zusätzlich ist Wien auch ein [[Bundesland]] und verfügt über eine eigene [[Wiener]] Landesregierung mit einem [[Wiener]] Bürgermeister, der auch [[Landeshauptmann]] von Wien ist."}]'::jsonb, ''),
  ('hauptschdodt-wean', 'Hauptschdodt Wean', '', '', '', '', 'Hauptstadt Wien', '[{"kategorie": "allg.", "text": "\"Hauptstadt Österreichs und eines der neun [[Bundesländer]] des Landes\""}, {"kategorie": "", "text": "Sie liegt im Osten Österreichs an der [[Donau]] und ist mit rund 2,1 Millionen Einwohnern die bevölkerungsreichste Stadt des Landes"}, {"kategorie": "", "text": "Wien ist ein wichtiges kulturelles, wirtschaftliches und politisches Zentrum in Europa. Die Stadt ist für ihre reiche Geschichte, Architektur und Musiktradition bekannt, darunter weltberühmte Institutionen wie die [[Wiener]] Staatsoper und das [[Schloss]] Schönbrunn"}, {"kategorie": "", "text": "Die Ursprünge Wiens reichen bis zur Römerzeit zurück, als die Stadt als Militärlager namens [[Vindobona]] gegründet wurde"}, {"kategorie": "", "text": "Über die Jahrhunderte entwickelte sich Wien zu einer Residenzstadt der [[Habsburger]] und wurde zum Zentrum des [[Heiligen]] Römischen Reiches und später der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Wien war das Herzstück des kaiserlichen Österreichs und spielte eine zentrale Rolle in Kunst, Musik, Architektur und Philosophie. Die Stadt beherbergt zahlreiche UNESCO-Weltkulturerbestätten wie das historische Zentrum und das [[Schloss]] Schönbrunn"}, {"kategorie": "", "text": "Wien ist zudem ein wichtiger internationaler Knotenpunkt und Sitz vieler internationaler Organisationen wie der Vereinten Nationen (UN) und der Organisation erdölexportierender Länder (OPEC). Die Stadt ist wirtschaftlich stark und bietet eine hohe Lebensqualität, was sie regelmäßig zu einem der besten Wohnorte weltweit macht"}, {"kategorie": "", "text": "Als Hauptstadt ist Wien der Sitz der österreichischen Bundesregierung, des Bundespräsidenten und zahlreicher Ministerien. Zusätzlich ist Wien auch ein [[Bundesland]] und verfügt über eine eigene [[Wiener]] Landesregierung mit einem [[Wiener]] Bürgermeister, der auch [[Landeshauptmann]] von Wien ist."}]'::jsonb, ''),
  ('da-bund', 'Da Bund', '', '', '', '', 'Der Bund', '[{"kategorie": "pol.", "text": "\"Der Staat Österreich auf der Ebene des gesamten Bundesgebietes\""}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, was bedeutet, dass es neben dem Bund auch aus neun Bundesländern besteht, die jeweils eigene gesetzgebende und ausführende Organe haben (siehe [[Föderalismus]])"}, {"kategorie": "", "text": "Der Bund ist jedoch für übergeordnete Angelegenheiten verantwortlich, wie die Außenpolitik, die Verteidigung, die Justiz und die Bundesgesetzgebung"}, {"kategorie": "", "text": "Der [[Nationalrat]] und der [[Bundesrat]] bilden die gesetzgebende Gewalt des Bundes, während die [[Bundesregierung]] die Exekutive verkörpert."}]'::jsonb, ''),
  ('oestarreich-ungarn', 'Östarreich-Ungarn', '', '', '', '', 'Österreich-Ungarn', '[{"kategorie": "allg.", "text": "\"[[Doppelmonarchie]], die von 1867 bis 1918 existierte und aus dem [[Kaiserreich]] Österreich und dem [[Königreich]] Ungarn bestand\""}, {"kategorie": "", "text": "Sie entstand durch den [[Ausgleich]] von 1867, der beiden Reichshälften weitgehende Autonomie gewährte, während Außenpolitik, Militär und Finanzen gemeinsam verwaltet wurden"}, {"kategorie": "", "text": "Das Reich Österreich-Ungarn umfasste weite Teile Mitteleuropas, darunter die heutigen Staaten Österreich, Ungarn, Tschechien, Slowakei, Kroatien, sowie Teile Italiens und der Ukraine"}, {"kategorie": "", "text": "Die [[Doppelmonarchie]] Österreich-Ungarn endete mit dem Zusammenbruch nach dem [[Ersten]] Weltkrieg 1918."}]'::jsonb, ''),
  ('pfoakiachn-schdammasduaf', 'Pfoakiachn Schdammasduaf', '', '', '', '', 'Pfarrkirche Stammersdorf', '[{"kategorie": "", "text": "Sie wurde im 18. Jahrhundert errichtet und ist durch ihre Barockfassade und den markanten Zwiebelturm ein weithin sichtbares Wahrzeichen des Ortskerns von Stammersdorf"}, {"kategorie": "", "text": "Die Fassade ist schlicht gehalten, mit symmetrischen Elementen und kleinen Verzierungen, die dem Barockstil entsprechen"}, {"kategorie": "", "text": "Im Inneren der Kirche befindet sich ein prächtiger Hochaltar, der typisch für die barocke Kirchenarchitektur ist. Der Altar ist reich mit Schnitzereien, Engelfiguren und vergoldeten Elementen verziert. Im Zentrum des Altars steht eine Statue des heiligen Nikolaus, dem Schutzpatron der Kirche"}, {"kategorie": "", "text": "Zudem sind mehrere Seitenaltäre und Gemälde zu sehen, die das Leben Jesu und der Heiligen darstellen. Die kunstvollen Fresken an der Decke und die detailreichen Heiligenfiguren betonen den sakralen Charakter der Kirche"}, {"kategorie": "", "text": "Die Pfarrkirche Stammersdorf ist nicht nur ein religiöses Zentrum, sondern auch ein kulturelles Wahrzeichen des Ortes. Von der erhöhten Position der Kirche hat man einen schönen Blick auf die umliegenden Weinberge und den [[Bisamberg]]."}]'::jsonb, ''),
  ('wiina-tradition', 'Wiina Tradition', '', '', '', '', 'Wiener Tradition', '[{"kategorie": "allg.", "text": "\"die kulturellen, historischen und gesellschaftlichen Bräuche Wiens, die tief in der Stadtgeschichte verwurzelt sind\""}, {"kategorie": "", "text": "Die Wiener Tradition reicht von der [[Wiener]] Kaffeehauskultur (die seit dem 17. Jahrhundert besteht und als Treffpunkt für Künstler, Intellektuelle und Literaten dient) bis hin zu den weltberühmten [[Heurigenlokalen]], wo der lokale Wein ausgeschenkt wird"}, {"kategorie": "", "text": "Die Wiener Tradition spiegelt sich auch in der Architektur wider. Prachtvolle Bauten wie das [[Schloss]] Schönbrunn, der [[Stephansdom]] und die [[Hofburg]] sind Zeugen der einstigen kaiserlichen Residenzstadt und prägen bis heute das Stadtbild"}, {"kategorie": "", "text": "Ein weiteres wichtiges Element ist die [[Wiener]] Klassik, mit Komponisten wie Mozart, Beethoven und Schubert, sowie der von [[Johann]] Strauß begründete [[Wiener]] Walzer"}, {"kategorie": "", "text": "Wien ist auch für seine Festkultur bekannt, wobei der [[Wiener]] Opernball eine der prestigeträchtigsten Veranstaltungen ist. Weitere festliche Traditionen sind der [[Christkindlmarkt]] in der Adventszeit und das [[Neujahrskonzert]] der [[Wiener]] Philharmoniker, das weltweit übertragen wird und den [[Wiener]] Walzer zelebriert"}, {"kategorie": "", "text": "Ein wichtiger Teil der Wiener Tradition ist auch die kulinarische Kultur. Gerichte wie das [[Wiener]] Schnitzel, der [[Apfelstrudel]] und die [[Sachertorte]] sind international bekannt"}, {"kategorie": "", "text": "Besonders hervorzuheben ist auch der traditionelle Besuch eines [[Heurigen]]. Diese Weinschenken, oft in den Wiener Vororten wie [[Stammersdorf]], [[Sievering]], [[Neustift]] am Walde und [[Grinzing]] gelegen, bieten lokalen Wein und einfache, regionale Speisen in gemütlicher Atmosphäre an"}, {"kategorie": "", "text": "Der Lebensstil der Wiener ist stark von einer Mischung aus Ruhe, Genuss und einem Hauch von kaiserlicher Eleganz geprägt. Dies zeigt sich im Konzept der à„Wiener Gemütlichkeit“, einer entspannten, doch kultivierten Lebensart"}, {"kategorie": "", "text": "Zusammengefasst ist die Wiener Tradition ein lebendiger Ausdruck der historischen und kulturellen Identität der Stadt. Sie verbindet die musikalische Hochkultur, kulinarische Spezialitäten und eine besondere Lebensweise zu einem einzigartigen Kulturraum, der weltweit anerkannt und geschätzt wird."}]'::jsonb, ''),
  ('wiina-klassik', 'Wiina Klassik', '', '', '', '', 'Wiener Klassik', '[{"kategorie": "allg.", "text": "\"bedeutende Epoche in der Musikgeschichte, die ungefähr von 1770 bis 1827 reicht und in der Wien zum Zentrum des musikalischen Schaffens in Europa wurde\""}, {"kategorie": "", "text": "Typisch für die Wiener Klassik sind klare musikalische Strukturen, Harmonie und Ausgewogenheit"}, {"kategorie": "", "text": "Während der Wiener Klassik wurde die klassische Musikform, insbesondere die Symphonie, das Streichquartett und die Sonate, maßgeblich weiterentwickelt"}, {"kategorie": "", "text": "Die Wiener Klassik ist besonders mit den Komponisten Joseph Haydn, Wolfgang Amadeus Mozart und Ludwig van Beethoven verbunden und steht damit für die Synthese von barocker Komplexität und klassischer Klarheit"}, {"kategorie": "", "text": "Zur Zeit der Wiener Klassik war Wien das kulturelle und musikalische Herz Europas, mit einem lebendigen Musikleben, das sowohl vom Adel als auch vom aufstrebenden Bürgertum gefördert wurde"}, {"kategorie": "", "text": "Haydn, Mozart und Beethoven wirkten über lange Zeiträume in Wien, und ihre Musik wurde maßgeblich von der Atmosphäre der Stadt beeinflusst."}]'::jsonb, ''),
  ('wiina-gemuetlichkeit', 'Wiina Gemütlichkeit', '', '', '', '', 'Wiener Gemütlichkeit', '[{"kategorie": "allg.", "text": "\"besondere Wiener Lebensart und Atmosphäre, die typisch für Wien und die Wiener ist\""}, {"kategorie": "", "text": "Sie steht für Entspannung, Gelassenheit und ein angenehmes, unaufgeregtes Zusammensein"}, {"kategorie": "", "text": "Diese Haltung zeigt sich vor allem in der [[Wiener]] Kaffeehauskultur, wo man Zeit hat, sich zurückzulehnen, das Leben zu genießen und sich in langen Gesprächen oder bei einem Kaffee zu entspannen"}, {"kategorie": "", "text": "\"Wiener Gemütlichkeit\" bedeutet,  Stress zu vermeiden und das Schöne im Alltag zu schätzen"}, {"kategorie": "", "text": "Wien bietet viele Orte, an denen diese Gelassenheit gelebt wird, von [[Heurigen]] bis zu den berühmten [[Kaffeehäusern]]"}, {"kategorie": "", "text": "Wiener Gemütlichkeit beschreibt somit eine spezielle Lebensart, die in Wien als Ausdruck von Ruhe, Genuss und einer entspannten Lebensweise verstanden wird."}]'::jsonb, ''),
  ('wiina-pfoate', 'Wiina Pfoate', '', '', '', '', 'Wiener Pforte', '[{"kategorie": "allg.", "text": "\"bedeutender geografischer Durchbruch, durch den die [[Donau]] zwischen den Hügeln des [[Leopoldsbergs]] und des [[Bisambergs]] fließt\""}, {"kategorie": "", "text": "Die Wiener Pforte ist besonders bemerkenswert, weil die Donau hier im Norden Wiens erstmals durch Wiener Stadtgebiet fließt"}, {"kategorie": "", "text": "Die Wiener Pforte markiert den Übergang der Donau vom Tullner Becken in das  [[Wiener]] Becken und ist eine strategisch wichtige Engstelle, durch die seit Jahrhunderten wichtige Handels- und Verkehrswege führen"}, {"kategorie": "", "text": "Die Wiener Pforte hat sowohl geographische als auch historische Bedeutung, da sie Wien von den nördlichen und westlichen Regionen trennt, als Tor zur Stadt fungiert und auch bei der Verteidigung Wiens über Jahrhunderte eine wichtige Rolle gespielt hat."}]'::jsonb, ''),
  ('pfoakiachn-jedlesee', 'Pfoakiachn Jedlesee', '', '', '', '', 'Pfarrkirche Jedlesee', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im Wiener Stadtteil [[Jedlesee]], der zum 21. Gemeindebezirk (Floridsdorf) gehört (offiziell \"Lorettokirche\")"}, {"kategorie": "", "text": "Die Kirche ist der Heiligen Maria Loretto geweiht ist und wurde Anfang des 18. Jahrhunderts als Wallfahrtskirche gestiftet"}, {"kategorie": "", "text": "Die Kirche verdankt ihre Existenz der Lorettokapelle, die im 18. Jahrhundert als Ort der Marienverehrung errichtet wurde. Diese Kapelle war ein bedeutendes religiöses Zentrum für die Dorfbewohner"}, {"kategorie": "", "text": "Im Jahr 1779 ließ der Arzt und Hofmediziner Anton von Störck die Lorettokapelle durch den Anbau eines Langhauses erweitern. Dieser Umbau verwandelte die Kapelle in eine größere Kirche, um den wachsenden Bedürfnissen der Gemeinde gerecht zu werden"}, {"kategorie": "", "text": "Die Lorettokirche zeichnet sich durch eine Mischung aus barocken und klassizistischen Stilelementen aus, die aus der Zeit der Erweiterung im 18. Jahrhundert stammen. Der ursprüngliche Kern der Kapelle, der bis heute erhalten ist, bleibt ein wichtiger Bestandteil der Kirche"}, {"kategorie": "", "text": "Der Innenraum ist schlicht, aber dennoch von einer gewissen barocken Eleganz geprägt. Besonders hervorzuheben ist der Hochaltar, der der Madonna von Loreto geweiht ist. Die Verehrung der Jungfrau Maria in der Loretto-Tradition spiegelt sich in vielen künstlerischen Details der Kirche wider."}]'::jsonb, ''),
  ('pfoakiachn-grossjedlasduaf', 'Pfoakiachn Großjedlasduaf', '', '', '', '', 'Pfarrkirche Großjedlersdorf', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im Wiener Stadtteil [[Großjedlersdorf]] im 21. Gemeindebezirk ([[Floridsdorf]]),  offiziell bekannt auch als \"Kirche zum heiligen Karl Borromäus\" bzw. \"Wallfahrtskirche Klein-Maria-Taferl\""}, {"kategorie": "", "text": "Die Kirche steht an einem markanten Punkt im alten Straßendorf [[Jedlersdorf]] und befindet sich im Gehsteigbereich der Amtsstraße, der Hauptstraße des ehemaligen Dorfes. Die Lage der Kirche ist so, dass sie die Amtsstraße im Bereich des Kirchengebäudes auf eine einspurige Fahrbahn verengt, was die historische Struktur des Ortes unterstreicht"}, {"kategorie": "", "text": "Während der Pest von 1713 gelobten die Dorfbewohner, eine Kapelle zu bauen, die dem Heiligen Karl Borromäus und der Heiligen Dreifaltigkeit geweiht war. Diese erste Kapelle wurde 1715 als einfacher Holzbau errichtet"}, {"kategorie": "", "text": "Eine berühmte Sage rankt sich um das Marienbild Klein-Maria-Taferl, das sich ursprünglich in der Kapelle befand. Als 1748 ein verheerender Brand Jedlersdorf zerstörte, warf man das Bild in die Flammen, doch es wurde später unversehrt unter den verkohlten Trümmern gefunden. Dieses Ereignis verstärkte die Verehrung des Bildes, das als \"Flammenmadonna\" bekannt wurde"}, {"kategorie": "", "text": "Zahlreiche Wallfahrer besuchten die Kirche, um vor der Madonna zu beten. Das Marienbild ist ein bedeutender Bestandteil der religiösen Geschichte der Kirche und der Region. Die Legende der Flammenmadonna, die sich um das Marienbild rankt, trug ebenfalls zur Bedeutung des Wallfahrtsorts bei"}, {"kategorie": "", "text": "Im Zuge der kirchlichen Reformen unter Josef II. wurde die Kirche 1783 zur eigenständigen Pfarre erklärt und dem Heiligen Karl Borromäus, dem Patron gegen die Pest, geweiht. In Erinnerung an die Pestepidemie wurde auch ein Friedhof am damaligen Ortsrand errichtet. Zwei Jahre später, 1785, wurde die Kirche erneut vergrößert und mit einem Turm versehen, um den gestiegenen Bedürfnissen der Gemeinde gerecht zu werden"}, {"kategorie": "", "text": "Das Hochaltarbild der Kirche, das den Heiligen Karl Borromäus darstellt, stammt aus dem Jahr 1838 und wurde von Anton Nigg gemalt. Die Kirche wurde zuletzt im Jahr 1931 renoviert, wobei auch das barocke Erscheinungsbild erhalten blieb."}]'::jsonb, ''),
  ('wiina-weinkultua', 'Wiina Weinkultua', '', '', '', '', 'Wiener Weinkultur', '[{"kategorie": "allg.", "text": "\"lebendige und traditionsreiche Kultur, die tief in der Geschichte und dem Alltag der Stadt Wien verwurzelt ist\""}, {"kategorie": "", "text": "Wien ist die einzige Hauptstadt weltweit, die innerhalb ihrer Stadtgrenzen nennenswerten Weinbau betreibt, was die Wiener Weinkultur einzigartig macht"}, {"kategorie": "", "text": "Diese Kultur umfasst nicht nur den Anbau von Wein, sondern auch die Tradition der Heurigen, die lokale Weinausschankstätten sind, sowie Feste und Rituale, die um den Wein und seine Herstellung kreisen"}, {"kategorie": "", "text": "Der Weinbau in Wien hat eine über 2000 Jahre alte Geschichte, die bis in die Zeit der Römer zurückreicht. Schon damals erkannten die Römer die fruchtbaren Böden und das milde Klima der Region und begannen mit dem Weinbau"}, {"kategorie": "", "text": "Über die Jahrhunderte entwickelte sich der Weinbau zu einem wichtigen Wirtschaftszweig der Stadt. Besonders in den Weinbaugebieten im Norden (wie [[Grinzing]], [[Neustift]] am Walde, [[Sievering]] und [[Nussdorf]] in [[Döbling]] und [[Großjedlersdorf]] und [[Stammersdorf]] in [[Floridsdorf]]) sowie im Süden ([[Mauer]] in [[Liesing]] und [[Oberlaa]] in [[Favoriten]]) wird seit langem Wein kultiviert"}, {"kategorie": "", "text": "Insgesamt gibt es in Wien rund 700 Hektar Weinanbaufläche. Mit ihren malerischen Weingärten, den gemütlichen [[Heurigen]] und den vielfältigen Weinsorten bietet die Wiener Weinkultur eine einzigartige Verbindung zwischen städtischem Leben und ländlicher Tradition und ist ein wesentlicher Bestandteil der Wiener Identität, die sowohl Weinkenner als auch Liebhaber geselliger Zusammenkünfte anzieht"}, {"kategorie": "", "text": "Ein zentraler Bestandteil der Wiener Weinkultur ist die [[Heurigenkultur]]. [[Heurige]] sind traditionelle Weinstuben oder Gasthäuser, in denen der Wein direkt von den Winzern ausgeschenkt wird. Der Name „Heuriger“ kommt vom österreichischen Wort „heurig“, was „diesjährig“ bedeutet und sich auf den frisch produzierten Wein des aktuellen Jahrgangs bezieht. Diese Lokale sind oft gemütlich und bieten eine einfache, aber herzhafte Küche an, die gut mit dem lokalen Wein harmoniert, wie [[Liptauer]], [[Brettljause]] oder [[Schmalzbrot]]"}, {"kategorie": "", "text": "Wien ist besonders bekannt für seinen [[Gemischten]] Satz, eine traditionelle Wiener Spezialität. Dabei handelt es sich um einen Wein, der aus verschiedenen Rebsorten besteht, die gemeinsam in einem Weingarten angebaut und geerntet werden. Dieser Wein vereint die Aromen und Charakteristika der verschiedenen Trauben zu einem unverwechselbaren Geschmack."}]'::jsonb, ''),
  ('schdrewasduafa-pfoakiachn', 'Schdrewasduafa Pfoakiachn', '', '', '', '', 'Strebersdorfer Pfarrkirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Pfarrkirche im Bezirksteil [[Strebersdorf]] des 21. Wiener Gemeindebezirks ([[Floridsdorf]]). Sie ist dem Fest Maria Königin geweiht und ist deshalb auch als \"Maria-Königin-Kirche\" bekannt"}, {"kategorie": "", "text": "Sie dient seit 1961 als Pfarrkirche der Pfarre [[Strebersdorf]]. Zuvor wurde die Klosterkirche \"Maria Immaculata\" in der Anton-Böck-Gasse als Pfarrkirche genutzt, die im 19. Jahrhundert als Teil des Klosters der [[Schulbrüder]] errichtet wurde"}, {"kategorie": "", "text": "Die Maria-Königin-Kirche ist ein modernes Kirchengebäude, das in den späten 1950er Jahren erbaut wurde. Der Bau spiegelt die schlichte und funktionale Architektur der Nachkriegszeit wider"}, {"kategorie": "", "text": "Die Pfarrkirche Maria Königin hat einen kreuzförmigen Grundriss mit T-förmig angeordnetem Lang- und Querschiff, der eine Gruppierung um den leicht vertieften Altarraum ermöglicht. Der erhöhte Altarraum wird von einem Lichtband beleuchtet. Nach dem Konzil wurde der Tabernakel in die Werktagskapelle verlegt, und der Altar dient nun als Volksaltar"}, {"kategorie": "", "text": "Über dem Hochaltar der Pfarrkirche Maria Königin hängt ein Kreuz von Alexander Silveri, das aus einer gespaltenen Kugel emporwächst und eine stilisierte Krone als Unterbau aufweist, symbolisierend das Patrozinium der Kirche."}]'::jsonb, ''),
  ('pfoakiachn-heaz-jesu', 'Pfoakiachn Heaz Jesu', '', '', '', '', 'Pfarrkirche Herz Jesu', '[{"kategorie": "allg.", "text": "\"römisch-katholische Filialkirche im Bezirksteil [[Strebersdorf]] des 21. Wiener Gemeindebezirks Floridsdorf\""}, {"kategorie": "", "text": "Sie ist dem Heiligen Herz Jesu geweiht und auch unter dem Namen \"Pfarr- und Karmelitinnenkirche Herz Jesu\" bekannt"}, {"kategorie": "", "text": "Der Orden der Karmelitinnen gründete 1917 ein Kloster in der Töllergasse, und 1923 begann der Bau einer Kirche im Klostergarten, finanziert von Graf Peter Vay de Vaya"}, {"kategorie": "", "text": "Die Kirche, nach Plänen von Bruno Buchwieser senior im Renaissancestil errichtet, wurde 1928 geweiht und ursprünglich dem heiligen Petrus geweiht. Daran erinnert eine Statue des Heiligen in einer Mauernische über dem Hauptportal"}, {"kategorie": "", "text": "1940 wurde sie zur Pfarrkirche erhoben und 1963 dem unbefleckten Herzen Mariens geweiht. Von 1970 bis 1971 erfolgte ein umfassender Umbau"}, {"kategorie": "", "text": "Der Hauptaltar sowie die Seitenaltäre der Kirche sind kunstvolle Schnitzarbeiten aus Gröden, einer Region, die für ihre Holzschnitzkunst bekannt ist"}, {"kategorie": "", "text": "1941 wurde die Kirche mit einer Orgel der Orgelbauanstalt Eberhard Friedrich Walcker aus Ludwigsburg ausgestattet, die seither das musikalische Herzstück der Kirche bildet"}, {"kategorie": "", "text": "1957 wurde an der Seitenfront des Klosters, zur Kirche hin, eine Muttergottesstatue der unbefleckten Empfängnis des Bildhauers Karl Nieschlag angebracht."}]'::jsonb, ''),
  ('schdrewasduafa-friidhof', 'Schdrewasduafa Friidhof', '', '', '', '', 'Strebersdorfer Friedhof', '[{"kategorie": "", "text": "Der Friedhof ist 26.362 Quadratmeter groß und verfügt über rund 1.400 Grabstellen. Besonderheiten sind die Kapelle und die Grabanlagen der [[Schulbrüder]]"}, {"kategorie": "", "text": "Nach der Eingemeindung von [[Strebersdorf]] nach Wien wurden Belagsbeschränkungen eingeführt, und 1923 wurde der Friedhof sogar vorübergehend geschlossen"}, {"kategorie": "", "text": "In den folgenden Jahren erfolgten mehrere Erweiterungen sowie Verbesserungen der baulichen Infrastruktur. Auf dem Strebersdorfer Friedhof befinden sich auch Gräber der [[Schulbrüder]], die 1965 mit neuen schmiedeeisernen Kreuzen nach einem Entwurf von Bruder Georg Schul versehen wurden"}, {"kategorie": "", "text": "Als lokaler Friedhof hat der Strebersdorfer Friedhof eine besondere Bedeutung für die Gemeinde, da hier seit vielen Jahrzehnten die Einwohner von Strebersdorf und den umliegenden Gebieten beigesetzt werden. Die familiäre Atmosphäre und die überschaubare Größe machen ihn zu einem Ort des persönlichen Gedenkens."}]'::jsonb, ''),
  ('donaucity-kiachn', 'Donaucity-Kiachn', '', '', '', '', 'Donaucity-Kirche', '[{"kategorie": "allg.", "text": "\"moderne römisch-katholische Kirche im Wiener Stadtteil [[Donaucity]] im 22. Wiener Gemeindebezirk ([[Donaustadt]]), offiziell auch \"Kirche Christus, Hoffnung der Welt\" genannt\""}, {"kategorie": "", "text": "Im Rahmen der Gestaltung des jungen Stadtteils [[Donau]] City in den 1990er Jahren wurde auch beschlossen, ein Kirchengebäude zu errichten. Es wurde ein Wettbewerb unter sechs anerkannten österreichischen Architekten veranstaltet. Der Wiener Architekt Heinz Tesar wurde von der Jury ausgewählt, da sein Projekt unabhängig von den rundum errichteten Hochhäusern bestehen konnte"}, {"kategorie": "", "text": "Die Kirche wurde zwischen 1999 und 2000 erbaut und ist architektonisch sowie religiös ein herausragendes Beispiel moderner Sakralarchitektur"}, {"kategorie": "", "text": "Die Donaucity-Kirche besteht aus steirischem Chromstahl und ist als Kirche nur durch ein weißes Kreuz und ein Stahlgerüst für die Glocken erkennbar. Das Gebäude ist ein Kreuzquader, dessen vier obere Ecken ausgeschnitten wurden. Die perforierte Stahlhülle mit runden Öffnungen erzeugt tagsüber Lichteffekte und lässt die Kirche nachts hell leuchten"}, {"kategorie": "", "text": "Der Innenraum ist mit Birkenholz gestaltet und von vielfältigem Lichteinfall geprägt, was die Atmosphäre erheblich beeinflusst. Die eingeschnittenen oberen Ecken schaffen eigene Zonen, darunter den Eingangsbereich, den Tabernakel, das Taufbecken und einen Bereich mit einer Madonnafigur"}, {"kategorie": "", "text": "Die Donaucity-Kirche steht unter Denkmalschutz. Unter der Kirche befinden sich ein Gemeindesaal, die Kanzlei, ein Foyer und mehrere Gruppenräume."}]'::jsonb, ''),
  ('jedlasduafa-schdrossn', 'Jedlasduafa Schdrossn', '', '', '', '', 'Jedlesdorfer Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Die Jedlesdorfer Straße beginnt im Bereich des Floridsdorfer Spitals (Krankenhaus Nord) und verläuft in Richtung Nordwesten durch den Stadtteil [[Jedlersdorf]]. Sie verbindet mehrere wichtige Straßen und Gebiete im Bezirk Floridsdorf und führt durch Wohn- und Geschäftsgebiete. Die Straße ist zudem eine wichtige Verbindungsroute für den öffentlichen Verkehr"}, {"kategorie": "", "text": "Die Jedlesdorfer Straße trägt den Namen des Stadtteils Jedlersdorf, einem ehemals eigenständigen Dorf, das 1904 nach Wien eingemeindet wurde. Die Straße war früher eine zentrale Achse, die das ländliche Jedlersdorf mit den benachbarten Siedlungen und dem Wiener Stadtzentrum verband. Auch heute spielt sie eine wichtige Rolle als Verbindungsstraße innerhalb des Bezirks"}, {"kategorie": "", "text": "Zu Jedlersdorf gehörte ursprünglich das ganze Gebiet zwischen [[Prager]] Straße und [[Brünner]] Straße einschließlich der Ansiedlung [[Jedlersdorf]] am Spitz (entstanden 1782); die Jedlersdorfer Straße ist auch ein alter Verbindungsweg zwischen [[Großjedlersdorf]] und [[Stammersdorf]]."}]'::jsonb, ''),
  ('leopoidaua-schdrossn', 'Leopoidaua Schdrossn', '', '', '', '', 'Leopoldauer Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Die Leopoldauer Straße beginnt im Süden von Floridsdorf und führt in nördlicher Richtung durch mehrere Stadtteile, darunter [[Großjedlersdorf]], [[Leopoldau]] und [[Jedlersdorf]]. Sie verläuft parallel zur [[Brünner]] Straße und erstreckt sich bis in den Stadtteil [[Leopoldau]], nach dem sie benannt ist"}, {"kategorie": "", "text": "Die Straße führt durch Wohn- und Gewerbegebiete und ist eine stark frequentierte Verkehrsachse."}]'::jsonb, ''),
  ('hofhea-schranz-gossn', 'Hofhea-Schranz-Gossn', '', '', '', '', 'Hofherr-Schrantz-Gasse', '[{"kategorie": "allg.", "text": "\"Straße im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), die nach dem bekannten Maschinenbauunternehmen Hofherr-Schrantz benannt wurde\""}, {"kategorie": "", "text": "Die Firma Hofherr-Schrantz zählte zu den bedeutendsten Herstellern von Landmaschinen in Österreich und spielte eine zentrale Rolle in der Industrialisierung Wiens"}, {"kategorie": "", "text": "Das Unternehmen Hofherr-Schrantz, offiziell bekannt als Hofherr-Schrantz-Clayton-Shuttleworth AG, entstand 1911 durch die Fusion der österreichischen Firma Hofherr-Schrantz mit dem britischen Landmaschinenhersteller Clayton & Shuttleworth. Beide Unternehmen waren führende Hersteller von Landmaschinen wie Traktoren, Mähdreschern und anderen landwirtschaftlichen Geräten"}, {"kategorie": "", "text": "Der Produktionsstandort in Floridsdorf spielte eine wichtige Rolle in der Herstellung dieser Maschinen und trug zur industriellen Entwicklung des Bezirks bei. Das Unternehmen war bis ins 20. Jahrhundert hinein ein bedeutender Arbeitgeber und ein wichtiger Teil der florierenden Maschinenbauindustrie in Österreich. 1970 ging das Unternehmen schließlich in den Böhler-Werken auf, was das Ende der eigenständigen Firma bedeutete."}]'::jsonb, ''),
  ('industriipark-wiin-noad', 'Industriipark Wiin Noad', '', '', '', '', 'Industriepark Wien Nord', '[{"kategorie": "allg.", "text": "\"bedeutendes Gewerbe- und Industriegebiet im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), das sich auf die Ansiedlung von Unternehmen aus verschiedenen Branchen spezialisiert hat\""}, {"kategorie": "", "text": "Der Industriepark liegt im Norden von Wien und ist einer der wichtigsten Standorte für Industrie und Logistik in der Stadt. Er befindet sich im Bereich der [[Shuttleworthstraße]] und [[Siemensstraße]], in der Nähe der Autobahn [[A]]22 ([[Donauuferautobahn]]), was eine hervorragende Anbindung an das Wiener Straßennetz gewährleistet"}, {"kategorie": "", "text": "Der Industriepark Wien Nord bietet Platz für zahlreiche Unternehmen aus den Bereichen Produktion, Logistik, Handel und Dienstleistungen. Durch seine Lage in einem traditionell industriell geprägten Teil Wiens zieht der Industriepark sowohl nationale als auch internationale Firmen an, die von der guten Infrastruktur und der Nähe zu Verkehrswegen profitieren."}]'::jsonb, ''),
  ('fluridsduafa-schbitz', 'Fluridsduafa Schbitz', '', '', '', '', 'Floridsdorfer Spitz', '[{"kategorie": "allg.", "text": "\"markantes geografisches und infrastrukturelles Gebiet im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Es bezeichnet den Bereich, wo sich mehrere Hauptverkehrsstraßen treffen und \"zu einem Spitz zusammenlaufen\", insbesondere die [[Prager]] Straße und die [[Brünner]] Straße, zwei wichtige Verkehrsachsen im Norden Wiens"}, {"kategorie": "", "text": "Der \"Spitz\" ist damit ein Knotenpunkt für den Autoverkehr, aber auch für den öffentlichen Verkehr, da sich dort auch zahlreiche Straßenbahn- und Buslinien kreuzen"}, {"kategorie": "", "text": "Darüber hinaus ist der Floridsdorfer Spitz ein wichtiger urbaner Raum, der verschiedene Einrichtungen des täglichen Lebens beherbergt, wie Geschäfte, Restaurants, Büros und Wohnhäuser. In der Nähe befindet sich auch der [[Floridsdorfer]] Bahnhof, ein wichtiger Verkehrsknotenpunkt für den öffentlichen Nah- und Fernverkehr in Wien"}, {"kategorie": "", "text": "Der Begriff \"Spitz\" bezieht sich auf die Form der Straßenzusammenführung, die einen \"spitzen\" Winkel bildet, weshalb der Bereich diesen Namen trägt. Es ist ein bekanntes und häufig frequentiertes Gebiet im nördlichen Teil Wiens."}]'::jsonb, ''),
  ('fluridsduafa-baunhof', 'Fluridsduafa Baunhof', '', '', '', '', 'Floridsdorfer Bahnhof', '[{"kategorie": "allg.", "text": "einer der bedeutendsten Bahnhöfe in Wien, der sich im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) befindet"}, {"kategorie": "", "text": "Er ist ein wichtiger Verkehrsknotenpunkt für den öffentlichen Nah- und Fernverkehr in der Stadt und Umgebung. Der Bahnhof verbindet den Norden Wiens mit anderen Stadtteilen und Regionen Österreichs und spielt eine zentrale Rolle für Pendler und Reisende"}, {"kategorie": "", "text": "Der Floridsdorfer Bahnhof wurde ursprünglich 1837 als Teil der Nordbahn eröffnet, die Wien mit Brünn (Brno) und später mit Krakau verband. Diese Bahnstrecke war die erste in Österreich und eine der wichtigsten Verbindungen, die zur wirtschaftlichen Entwicklung des Raumes nördlich der Donau beitrug. Im Laufe der Zeit wurde der Bahnhof mehrmals modernisiert und erweitert, um den steigenden Anforderungen des Personen- und Güterverkehrs gerecht zu werden"}, {"kategorie": "", "text": "Der Bahnhof liegt im Herzen des Bezirks [[Floridsdorf]], nördlich der [[Donau]], nahe dem sogenannten [[Floridsdorfer]] Spitz, einem markanten Verkehrsknotenpunkt. Diese zentrale Lage macht den Bahnhof zu einem unverzichtbaren Bestandteil des täglichen Lebens in der Region, da er sowohl innerstädtische als auch regionale Verbindungen bietet. Er verbindet den Norden Wiens mit dem Stadtzentrum und ist ein wichtiges Bindeglied zwischen Wien und Niederösterreich"}, {"kategorie": "", "text": "Die U6, eine der wichtigsten U-Bahn-Linien Wiens, endet bzw. beginnt am Floridsdorfer Bahnhof. Die U6 verläuft in Nord-Süd-Richtung und verbindet Floridsdorf mit den südlichen Teilen der Stadt, darunter wichtige Knotenpunkte wie den Westbahnhof und den Bahnhof Meidling. Diese Linie bietet schnellen Zugang zum Stadtzentrum und verbindet den Bahnhof mit anderen Bezirken und Umsteigemöglichkeiten zu weiteren U-Bahn-Linien."}]'::jsonb, ''),
  ('schlosshofa-schdrossn', 'Schlosshofa Schdrossn', '', '', '', '', 'Schloßhofer Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Die Schloßhofer Straße beginnt im Süden am [[Floridsdorfer]] Bahnhof, einem wichtigen Verkehrsknotenpunkt, und führt in Richtung Norden bis zur Grenze von Wien und dem niederösterreichischen Umland"}, {"kategorie": "", "text": "Von dort aus setzt sie sich bis in den niederösterreichischen Ort \"Schlosshof\" fort (Standort des größten der sechs Marchfeldschlösser), was der Straße ihren Namen gibt"}, {"kategorie": "", "text": "Auf ihrem Weg durch Floridsdorf durchquert die Schloßhofer Straße wichtige Stadtviertel und verbindet Wohn- und Geschäftsgebiete"}, {"kategorie": "", "text": "Die Straße ist nicht nur eine wichtige Durchgangsstraße, sondern auch ein zentraler Ort für das tägliche Leben der Anwohner, mit einer Vielzahl von Geschäften, Dienstleistungsangeboten und öffentlichen Einrichtungen entlang ihres Verlaufs."}]'::jsonb, ''),
  ('angara-schdrossn', 'Angara Schdrossn', '', '', '', '', 'Angerer Straße', '[{"kategorie": "allg.", "text": "zentrale Verkehrs- und Geschäftsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Die Angerer Straße beginnt im Osten in der Nähe des [[Floridsdorfer]] Bahnhofs, einem der wichtigsten Verkehrsknotenpunkte Wiens, und führt in westlicher Richtung durch Floridsdorf und schließlich bis zum Ort \"Angern an der March\" in Niederösterreich, 37 Kilometer von Wien entfernt, nach welchem sie benannt ist"}, {"kategorie": "", "text": "Die Straße spielt eine wichtige Rolle im täglichen Leben der Anwohner, ist ein bedeutender Teil des öffentlichen Verkehrsnetzes und bietet zahlreiche Einkaufsmöglichkeiten sowie Dienstleistungen"}, {"kategorie": "", "text": "Mit ihrer Mischung aus Wohn- und Geschäftsgebäuden ist die Angerer Straße ein lebendiger, urbaner Raum und ein wichtiger Bestandteil der Infrastruktur des Bezirks Floridsdorf."}]'::jsonb, ''),
  ('aum-schbitz', 'Aum Schbitz', '', '', '', '', 'Am Spitz', '[{"kategorie": "allg.", "text": "\"zentraler Platz und ein bedeutender Verkehrsknotenpunkt im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Er liegt im Herzen des Bezirks und ist eines der wichtigsten urbanen Zentren in diesem Teil Wiens;  3.Der Name \"Am Spitz\" bezieht sich auf die spitz zulaufende Form der Kreuzung, an der mehrere Hauptverkehrsstraßen, darunter die [[Brünner]] Straße, [[Prager]] Straße und [[Schloßhofer]] Straße, aufeinandertreffen"}, {"kategorie": "", "text": "Der Platz \"Am Spitz\" befindet sich in unmittelbarer Nähe des [[Floridsdorfer]] Bahnhofs und bildet somit das Zentrum des Bezirks [[Floridsdorf]]. Er ist ein zentraler Anlaufpunkt für den öffentlichen Verkehr und auch ein wirtschaftliches Zentrum mit zahlreichen Geschäften, Büros und öffentlichen Einrichtungen"}, {"kategorie": "", "text": "Der Bereich \"Am Spitz\" bildet das Herz von [[Floridsdorf]] und hat sich in den letzten Jahrzehnten kontinuierlich weiterentwickelt. Wichtige Einrichtungen wie Banken, Apotheken und Einkaufszentren sind ebenfalls in unmittelbarer Nähe vorhanden. Dies macht den Platz \"Am Spitz\" zu einem lebendigen und stark frequentierten urbanen Zentrum von Floridsdorf."}]'::jsonb, ''),
  ('franz-jonas-plotz', 'Franz-Jonas-Plotz', '', '', '', '', 'Franz-Jonas-Platz', '[{"kategorie": "allg.", "text": "\" zentraler Platz im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) und ein bedeutender Verkehrsknotenpunkt im Norden Wiens\""}, {"kategorie": "", "text": "Der Franz-Jonas-Platz liegt im Herzen des Bezirks Floridsdorf, unmittelbar vor dem [[Floridsdorfer]] Bahnhof, an einem der wichtigsten Verkehrsknotenpunkte im Norden Wiens. Er ist umgeben von wichtigen Verkehrsachsen, wie der [[Schloßhofer]] Straße und der [[Angerer]] Straße, die Floridsdorf mit anderen Teilen Wiens verbinden"}, {"kategorie": "", "text": "Der Platz ist nach Franz Jonas (1899–1974) benannt, einem bedeutenden österreichischen Politiker, der von 1965 bis 1974 als Bundespräsident der [[Republik]] Österreich amtierte. Zuvor war Jonas von 1951 bis 1965 Bürgermeister von Wien und trug maßgeblich zur Modernisierung der Stadt nach dem Zweiten Weltkrieg bei"}, {"kategorie": "", "text": "Der Platz spielt eine zentrale Rolle im städtischen Leben von Floridsdorf und dient als wichtige Drehscheibe für den öffentlichen Verkehr sowie als urbanes Zentrum für Handel, Dienstleistungen und Freizeit."}]'::jsonb, ''),
  ('aun-da-obaren-oitn-donau', 'Aun da Obaren Oitn Donau', '', '', '', '', 'An der Oberen Alten Donau', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im Norden von Wien, die sich entlang des Nordufers der [[Alten]] Donau erstreckt, einem Altarm der [[Donau]], der heute ein beliebtes Naherholungsgebiet darstellt\""}, {"kategorie": "", "text": "Sie befindet sich im 21. Wiener Gemeindebezirk (Floridsdorf) und erstreckt sich von der [[Floridsdorfer]] Brücke in Richtung Westen entlang den Ufern der Alten Donau bis zur [[Wagramer]] Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]])"}, {"kategorie": "", "text": "Die Alte Donau selbst ist ein stillgelegter Teil der Donau, der nach der Regulierung des Flusses im 19. Jahrhundert von der Hauptströmung abgetrennt wurde und seither als ruhiges Gewässer dient. Es ist ein natürliches Erholungsgebiet und bietet eine malerische Kulisse für Anwohner und Besucher."}]'::jsonb, ''),
  ('fluridsduafa-moakd', 'Fluridsduafa Moakd', '', '', '', '', 'Floridsdorfer Markt', '[{"kategorie": "allg.", "text": "\"bekannter Markt im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Er liegt im Herzen des Bezirks und ist einer der traditionsreichsten Märkte in Wien, auch bekannt als [[Schlingermarkt]]. Der Markt befindet sich an der [[Brünner]] Straße, in der Nähe des [[Floridsdorfer]] Bahnhofs, und ist seit vielen Jahrzehnten ein beliebter Treffpunkt für Anwohner und Besucher aus der Umgebung"}, {"kategorie": "", "text": "Der Floridsdorfer Markt wurde bereits in den 1920er Jahren gegründet und hat sich im Laufe der Zeit zu einem wichtigen Versorgungszentrum im Bezirk entwickelt. Der Name \"Schlingermarkt\" geht auf den damaligen Stadtbaumeister Hans Schlinger zurück, der für den Bau und die Planung des Marktes verantwortlich war"}, {"kategorie": "", "text": "Der Markt bietet eine breite Auswahl an frischen Lebensmitteln und internationalen Spezialitäten und ist ein wichtiger Bestandteil des lokalen Lebens in Floridsdorf. Mit seiner Mischung aus Tradition und Moderne bleibt der Floridsdorfer Markt ein einzigartiger und unverwechselbarer Teil Wiens"}]'::jsonb, ''),
  ('pius-parsch-plotz', 'Pius-Parsch-Plotz', '', '', '', '', 'Pius-Parsch-Platz', '[{"kategorie": "allg.", "text": "\"Platz im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), der nach dem Priester und Liturgiewissenschaftler Pius Parsch (1884–1954) benannt ist\""}, {"kategorie": "", "text": "Pius Parsch war ein bedeutender Vertreter der liturgischen Erneuerung in der katholischen Kirche und wirkte lange Zeit in der Klosterneuburger Pfarre St. Gertrud, was zu seiner Verehrung in der Region beitrug"}, {"kategorie": "", "text": "Der Pius-Parsch-Platz liegt in der Nähe des [[Bahnhofs]] Floridsdorf, einem wichtigen Verkehrsknotenpunkt im Norden Wiens, und ist verkehrstechnisch gut erschlossen. 4. Direkt am Pius-Parsch-Platz befindet sich auch die [[Pfarrkirche]] Floridsdorf, die dem Heiligen Jakobus dem Älteren geweiht ist (deshalb auch \"Jakobskirche\" genannt)"}, {"kategorie": "", "text": "Mit seiner zentralen Lage und der guten Anbindung an öffentliche Verkehrsmittel ist der Platz ein wichtiger Verkehrsknotenpunkt und Treffpunkt für die Bewohner des Bezirks."}]'::jsonb, ''),
  ('pfoakiachn-fluridsduaf', 'Pfoakiachn Fluridsduaf', '', '', '', '', 'Pfarrkirche Floridsdorf', '[{"kategorie": "", "text": "Sie ist dem Heiligen Jakobus dem Älteren geweiht und gehört zu den wichtigsten Sakralbauten im 21. Wiener Gemeindebezirk"}, {"kategorie": "", "text": "Die heutige Pfarrkirche St. Jakob wurde im Rahmen des ständestaatlichen Kirchenbauprogramms errichtet, das in den 1930er Jahren von der Regierung Österreichs gefördert wurde. Der Entwurf für die neue Kirche stammt von dem renommierten Architekten Robert Kramreiter, einem wichtigen Vertreter der modernen Sakralarchitektur. Der Neubau begann 1939 und wurde während des Zweiten Weltkriegs 1941 abgeschlossen"}, {"kategorie": "", "text": "Die heutige Jakobskirche zeichnet sich durch ihre markante schlichte, modernistische Architektur aus. Sie ist ein Beispiel für den Kirchenbau der späten 1930er Jahre in Wien, der sich von barocken und neogotischen Stilformen abwendete und stattdessen auf eine nüchterne, funktionale Gestaltung setzte"}, {"kategorie": "", "text": "Die Fassade ist schlicht, aber imposant, mit einem dominierenden Kirchturm, der das Stadtbild von Floridsdorf prägt."}]'::jsonb, ''),
  ('edmund-hawranek-plotz', 'Edmund-Hawranek-Plotz', '', '', '', '', 'Edmund-Hawranek-Platz', '[{"kategorie": "allg.", "text": "Platz im Wiener Stadtteil [[Strebersdorf]], der Teil des 21. Wiener Gemeindebezirks ([[Floridsdorf]]) ist"}, {"kategorie": "", "text": "Der Platz wurde 1964 nach dem Kaplan Edmund Hawranek (1874–1944) benannt, der eine zentrale Rolle im kirchlichen und gesellschaftlichen Leben von [[Strebersdorf]] spielte"}, {"kategorie": "", "text": "Edmund Hawranek wurde am 9. Mai 1874 in Wien geboren und starb am 23. Jänner 1944 ebenfalls in Wien. Er war Kaplan und Seelsorger, wirkte ab 1908 in der Pfarre Strebersdorf und setzte sich dort stark für die Anliegen der Gemeindebewohner ein"}, {"kategorie": "", "text": "Neben seiner Tätigkeit als Priester war Hawranek auch als Religionslehrer tätig und erwarb sich besondere Verdienste in der Erziehung sprachgestörter Kinder. Seine pädagogische Arbeit sowie sein soziales Engagement hinterließen bleibende Spuren in der Region"}, {"kategorie": "", "text": "Der Edmund-Hawranek-Platz liegt im Zentrum von [[Strebersdorf]] und ist ein wichtiger öffentlicher Raum in diesem Teil von [[Floridsdorf]]. Der Platz befindet sich in der Nähe der Strebersdorfer Kirche ([[Pfarrkirche]] Strebersdorf) und ist ein Treffpunkt für die Bewohner der Gegend."}]'::jsonb, ''),
  ('jedleseea-friidhof', 'Jedleseea Friidhof', '', '', '', '', 'Jedleseer Friedhof', '[{"kategorie": "", "text": "Der neue Friedhof befindet sich an der Liesneckgasse 14 und Audorfgasse 47 und erstreckt sich über eine Fläche von 56.067 Quadratmetern. Der Friedhof verfügt über rund 8.450 Grabstellen und weist einige Besonderheiten auf, darunter sowjetische Kriegsgräber aus dem Zweiten Weltkrieg, die an die gefallenen Soldaten der Roten Armee erinnern. Diese Kriegsgräberanlage wurde 1990 saniert"}, {"kategorie": "", "text": "Zu den hier bestatteten Persönlichkeiten zählen unter anderem die Besitzer der Jedleseer Brauerei, Anton Bosch und Anton Dengler, die in der lokalen Geschichte eine bedeutende Rolle spielten"}, {"kategorie": "", "text": "Der Jedleseer Friedhof präsentiert sich als ruhiger, stimmungsvoller Ort, der durch seine gepflegte Anlage und die teilweise aufwändigen Grabstätten eine gewisse bürgerliche Wohlhabenheit widerspiegelt. Die Verabschiedungshalle, die ursprünglich in den 1960er Jahren errichtet und mehrfach renoviert wurde, bietet einen modernen Raum für Trauerfeiern."}]'::jsonb, ''),
  ('oidmaunnsduafa-friidhof', 'Oidmaunnsduafa Friidhof', '', '', '', '', 'Altmannsdorfer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 3.807 Quadratmetern und 557 Grabstellen ist er einer der kleineren Friedhöfe Wiens. Eine Besonderheit des Friedhofs ist ein Friedhofskreuz aus dem Jahr 1853, das heute noch auf dem Gelände steht"}, {"kategorie": "", "text": "Das Mausoleum der Familie Hoffinger wurde 1846 errichtet, sie stiftete auch das Friedhofskreuz. Der Gründer der Ersten österreichischen Spar-Casse, Johann Baptist Weber, ist in einem Ehrengrab bestattet. Kreuz und Mausoleum wurden 1982 renoviert"}, {"kategorie": "", "text": "Ein weiteres bedeutendes Element ist das Kriegerdenkmal am Eingang des Friedhofs, das an die Opfer des Ersten Weltkriegs erinnert"}, {"kategorie": "", "text": "Die Aufbahrungshalle, die in den 1930er Jahren hinzugefügt wurde, sowie das Mausoleum des Grundherrn Hoffmann aus dem Jahr 1846 sind ebenfalls wichtige architektonische Bestandteile des Friedhofs."}]'::jsonb, ''),
  ('aschbana-friidhof', 'Aschbana Friidhof', '', '', '', '', 'Asperner Friedhof', '[{"kategorie": "", "text": "Der alte Asperner Friedhof befand sich ursprünglich direkt bei der [[Asperner]] Pfarrkirche St. Martin. Als der alte Friedhof zu klein wurde, beschloss die Gemeinde Aspern im Jahr 1892, einen neuen Friedhof im sogenannten Krautgarten anzulegen"}, {"kategorie": "", "text": "Heute umfasst der Asperner Friedhof eine Fläche von 73.432 Quadratmetern und rund 8.400 Grabstellen"}, {"kategorie": "", "text": "Ein zentrales Element des Friedhofs ist das Kriegerdenkmal, das den Opfern der beiden Weltkriege gewidmet ist. Auf einem hohen Steinsockel befindet sich eine Inschrift, die an die Kriegsopfer erinnert"}, {"kategorie": "", "text": "Zusätzlich gibt es ein Mauerstück mit einer Gedenktafel, die an die gefallenen Soldaten der sowjetischen Armee erinnert. Diese wird von zwei Pyramiden mit Sowjetsternen flankiert. Die Kriegsgräberanlage der sowjetischen Armee wurde 1990 in Zusammenarbeit mit dem Bundesministerium für Inneres saniert"}, {"kategorie": "", "text": "Eine weitere Besonderheit ist das Friedhofskreuz aus dem Jahr 1893, das von Theresia Parton gestiftet wurde. Sie erhielt als Dank eine Doppelgruft an der Friedhofsmauer für ihren verstorbenen Gatten"}, {"kategorie": "", "text": "Die Grabstätten der ehemaligen Asperner Oberschicht befinden sich im hinteren Teil des Friedhofs, an der alten Mauer. Diese Grabstätten spiegeln die Geschichte und den sozialen Status der dort beerdigten Personen wider"}, {"kategorie": "", "text": "In den letzten Jahrzehnten wurde der Friedhof kontinuierlich modernisiert. 2016 wurde die alte Aufbahrungshalle abgerissen, und die frei gewordenen Flächen wurden für Urnengräber genutzt."}]'::jsonb, ''),
  ('braadnleea-friidhof', 'Braadnleea Friidhof', '', '', '', '', 'Breitenleer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 11.987 Quadratmetern und etwa 1.220 Grabstellen dient er als Begräbnisstätte für die Bewohner des Stadtteils Breitenlee und der umliegenden Gebiete"}, {"kategorie": "", "text": "Der Friedhof wurde im Jahr 1909 angelegt und seither mehrfach erweitert, um den wachsenden Bedürfnissen der Bevölkerung gerecht zu werden"}, {"kategorie": "", "text": "Der Friedhof verfügt über einen speziellen Bereich für die Beerdigung von Nicht-Katholiken, was für einen ursprünglich konfessionellen Friedhof eher ungewöhnlich ist und eine offene Haltung gegenüber anderen Glaubensrichtungen zeigt"}, {"kategorie": "", "text": "Die moderne Aufbahrungshalle, errichtet im Jahr 2001, ist ein zentrales Element des Friedhofs und bietet einen würdevollen Rahmen für Trauerfeiern. Der großzügige Aufbahrungsraum ist mit hochwertigen Materialien ausgestattet und künstlerisch gestaltet."}]'::jsonb, ''),
  ('braadnleea-schdrossn', 'Braadnleea Schdrossn', '', '', '', '', 'Breitenleer Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 22. Wiener Gemeindebezirk ([[Donaustadt]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom zentralen Teil der Donaustadt bis in den ländlicheren Stadtteil [[Breitenlee]], nach dem sie auch benannt ist"}, {"kategorie": "", "text": "Die Straße spielt eine bedeutende Rolle in der Verbindung zwischen den innerstädtischen Bereichen Wiens und den äußeren, suburbanen Gebieten der Donaustadt"}, {"kategorie": "", "text": "An der Breitenleer Straße Nr. 231 befindet sich auch der [[Breitenleer]] Friedhof, der am nördlichen Ende der Straße liegt"}, {"kategorie": "", "text": "Außerdem gibt es entlang der Straße zahlreiche historische Häuser und Gebäude, die an die landwirtschaftliche Vergangenheit von [[Breitenlee]] und den benachbarten Stadtteilen erinnern."}]'::jsonb, ''),
  ('doanbocha-friidhof', 'Doanbocha Friidhof', '', '', '', '', 'Dornbacher Friedhof', '[{"kategorie": "", "text": "Er liegt an der [[Alszeile]] 28 und ist mit einer Fläche von 44.071 Quadratmetern und etwa 4.800 Grabstellen ein bedeutender Friedhof in diesem Teil Wiens"}, {"kategorie": "", "text": "Der Dornbacher Friedhof liegt an einem stark ansteigenden Hang in Richtung der Als und ist somit, ebenso wie der angrenzende [[Hernalser]] Friedhof, auf schwierigem Gelände gebaut. Dieser Bergfriedhof-Charakter gibt dem Friedhof eine besondere Atmosphäre, auch wenn das steile Gelände für Friedhofszwecke eher ungünstig ist. Die Topografie macht den Friedhof jedoch einzigartig und verleiht ihm einen idyllischen und ruhigen Charakter, der durch die Natur und das ansteigende Gelände verstärkt wird"}, {"kategorie": "", "text": "Auf dem Dornbacher Friedhof befanden sich einst auch die Gräber der nationalsozialistischen Juliputschisten von 1934, darunter Otto Planetta und Franz Holzweber. Diese Gräber wurden jedoch während des Zweiten Weltkriegs durch Bombentreffer zerstört"}, {"kategorie": "", "text": "Der neue Friedhof wurde am 26. Juli 1883 geweiht, und der Tischlermeister Adolf Hörmann war der erste Verstorbene, der am selben Tag beerdigt wurde"}, {"kategorie": "", "text": "Auf Grundlage der Friedhofsordnung vom 1. Dezember 1882 wurde der neue Friedhof für alle Konfessionen und auch Konfessionslose angelegt, was für die damalige Zeit eher ungewöhnlich war und für eine offene Haltung der Gemeinde sprach."}]'::jsonb, ''),
  ('esslinga-friidhof', 'Esslinga Friidhof', '', '', '', '', 'Esslinger Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 17.891 Quadratmetern und rund 1.800 Grabstellen ist er ein kleiner, ländlich geprägter Friedhof, der von Kleingartensiedlungen und Äckern umgeben ist. Der Friedhof bietet eine ruhige, naturnahe Umgebung und spiegelt die ländliche Vergangenheit des Stadtteils [[Essling]] wider"}, {"kategorie": "", "text": "Der genaue Zeitpunkt der Errichtung des Esslinger Friedhofs lässt sich nicht eindeutig klären, doch vermutlich wurde er um das Jahr 1789 angelegt, als Essling zur Lokalkaplanei erhoben wurde"}, {"kategorie": "", "text": "Eine erste Erweiterung des etwa 800 Meter nordöstlich der [[Esslinger]] Pfarrkirche gelegenen Friedhofs fand im Jahr 1842 statt. Das älteste erhaltene Grab stammt aus dem Jahr 1897, was die lange Nutzungsgeschichte des Friedhofs unterstreicht"}, {"kategorie": "", "text": "Während des Zweiten Weltkriegs, im Jahr 1941, wurde ein Aufbahrungsraum geschaffen, der dann 1952 vergrößert und 1970 renoviert wurde. In den Jahren 1969 und 1979 kamen zusätzliche Gräbergruppen hinzu, um den steigenden Platzbedarf zu decken."}]'::jsonb, ''),
  ('geaschdhofa-friidhof', 'Geaschdhofa Friidhof', '', '', '', '', 'Gersthofer Friedhof', '[{"kategorie": "", "text": "Trotz Plänen zur Schließung wurde der Friedhof 1980 durch eine Volksbefragung gerettet und bietet weiterhin eine wichtige Begräbnisstätte für die lokale Bevölkerung"}, {"kategorie": "", "text": "Der Gersthofer Friedhof wurde am 27. Oktober 1880 eingeweiht, nachdem der ursprüngliche Friedhof zu klein geworden war. Mit der Eingemeindung Gersthofs im Jahr 1892 ging der Friedhof in die Zuständigkeit der Wiener Stadtverwaltung über. Erste Erweiterungen des Friedhofs erfolgten bereits ab 1899, als eine zusätzliche Grundfläche von 20.000 Quadratmetern angekauft wurde. Ein Teil dieser Fläche, etwa 8.262 Quadratmeter, wurde im Jahr 1901 in den Friedhof integriert"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg wurden umfassende Renovierungsarbeiten vorgenommen, darunter die Instandsetzung der Aufbahrungshalle und die Errichtung einer neuen Friedhofsglocke. Zudem befindet sich auf dem Friedhof ein Massengrab von russischen Soldaten, die während des Krieges beigesetzt wurden"}, {"kategorie": "", "text": "Mit seiner Lage am Alsrücken, seinen 4.600 Grabstellen und dem Kriegerdenkmal bleibt der Gersthofer Friedhof ein zentraler Ort des Gedenkens und der Geschichte in Wien."}]'::jsonb, ''),
  ('friidhof-hadaschduaf-weidlingau', 'Friidhof Hadaschduaf-Weidlingau', '', '', '', '', 'Friedhof Hadersdorf-Weidlingau', '[{"kategorie": "", "text": "Mit einer Fläche von 13.229 Quadratmetern und rund 1.850 Grabstellen ist er ein bedeutender historischer Friedhof, der durch seine besondere Friedhofskapelle im Wiener Sezessionstil von Max Hegele (1909) und das schmiedeeiserne Barockkreuz aus dem alten Mariabrunner Friedhof hervorsticht"}, {"kategorie": "", "text": "Der Hadersdorf-Weidlingauer Friedhof wurde im Jahr 1875 als neuer Ortsfriedhof errichtet, nachdem der alte Mariabrunner Friedhof, der südöstlich des Klosters Mariabrunn gelegen war, aus sanitären Gründen und durch den Erlass des Ministeriums für Ackerbau geschlossen werden musste. Die Weihe des Friedhofs fand am 28. Juni 1875 statt, und das erste Begräbnis erfolgte kurz darauf, am 1. Juli 1875"}, {"kategorie": "", "text": "Die im Jahr 1909 erbaute Friedhofskapelle im Sezessionstil von Max Hegele ist eines der herausragenden Merkmale des Friedhofs. Sie wurde im Jugendstil gestaltet und ist sowohl architektonisch als auch künstlerisch von großer Bedeutung. Die Kapelle wurde in Zusammenarbeit mit dem Bundesdenkmalamt 1985 renoviert"}, {"kategorie": "", "text": "Das schmiedeeiserne Barockkreuz mit einem reich verzierten Blechschnitt und einem doppelseitigen Widmungsschild befindet sich über den Gebeinen der Verstorbenen aus dem alten Mariabrunner Friedhof, die 1921 auf den neuen Friedhof überführt wurden"}, {"kategorie": "", "text": "Der Friedhof beherbergt mehrere Jugendstilgräber, darunter die Gruft der Familie Eduard Herzmansky, die ebenfalls von Max Hegele entworfen wurde. Die Goldmosaiken und prächtigen Verzierungen dieser Gräber machen sie zu bedeutenden Beispielen der damaligen Grabmalkunst"}, {"kategorie": "", "text": "Das Ehrengrab des Architekten Max Hegele († 1945) wurde 1985 von der Stadt Wien auf Dauer gesichert und in den Friedhof aufgenommen."}]'::jsonb, ''),
  ('friidhof-grossjedlasduaf', 'Friidhof Grossjedlasduaf', '', '', '', '', 'Friedhof Großjedlersdorf', '[{"kategorie": "", "text": "Mit einer Fläche von 58.263 Quadratmetern und etwa 6.600 Grabstellen ist er ein bedeutender Friedhof für die Region und ein typischer Gemeindefriedhof, der seit dem 19. Jahrhundert die letzte Ruhestätte für viele Bewohner von [[Großjedlersdorf]] und Umgebung ist"}, {"kategorie": "", "text": "Der Alte Großjedlersdorfer Friedhof wurde im Jahr 1783 anlässlich der Erhebung von [[Großjedlersdorf]] zur eigenen Pfarre, im Zusammenhang mit der Großjedlersdorfer Kirche ([[Pfarrkirche]] Großjedlersdorf), errichtet"}, {"kategorie": "", "text": "Der ursprüngliche Friedhof wurde jedoch im Laufe der Zeit zu klein, insbesondere aufgrund des Bevölkerungswachstums in der zweiten Hälfte des 19. Jahrhunderts. Daher entschloss man sich, einen neuen und geräumigeren Friedhof gegenüber dem alten Gelände auf Gemeindegrund zu errichten. Dieser neue Friedhof wurde am 18. Juli 1872 feierlich geweiht"}, {"kategorie": "", "text": "Obwohl sich nur wenige ältere Gräber aus dem späten 19. Jahrhundert erhalten haben, sind einige der erhaltenen Gräber besonders interessant. Dazu gehören unter anderem die Gräber des Stammersdorfer Roma- und Sinti-Adels, die sich in der Nähe des Eingangs befinden"}, {"kategorie": "", "text": "Auch Stadtbaumeister Anton Schlinger, nach dem der [[Schlingerhof]] und der [[Schlingermarkt]] benannt sind, wurde 1912 auf dem Großjedlersdorfer Friedhof beigesetzt"}, {"kategorie": "", "text": "Der Großjedlersdorfer Friedhof zeichnet sich durch seine kontinuierlichen Erweiterungen und Modernisierungen aus. Besonders bemerkenswert ist die Aufbahrungshalle, die in den Jahren 1981/1982 von Erich Boltenstern neu gestaltet wurde. Sie erhielt eine moderne künstlerische Ausstattung mit einem Altarkreuz, einem Altarmosaik und Betondickglasfenstern, die von Hermann Bauch entworfen wurden. Die Aufbahrungshalle ist somit ein zentraler Bestandteil des Friedhofs und ein Beispiel für die Verbindung von moderner Kunst und traditioneller Friedhofsarchitektur."}]'::jsonb, ''),
  ('friidhof-hiaschschdettn', 'Friidhof Hiaschschdettn', '', '', '', '', 'Friedhof Hirschstetten', '[{"kategorie": "", "text": "Die Weihe des Friedhofs fand am 21. April 1872 statt, jedoch wurde die erste Bestattung erst 1878 vorgenommen"}, {"kategorie": "", "text": "Aufgrund des Bevölkerungswachstums ersuchte die Gemeinde jedoch um die Errichtung eines eigenen Friedhofs. Am 8. August 1871 genehmigte die Bezirkshauptmannschaft Groß-Enzersdorf den Bau des Hirschstettner Friedhofs, der außerhalb des Ortes an einem Feldweg nach Breitenlee errichtet wurde. Eine Voraussetzung für die Genehmigung war der Bau einer Totenkammer und die Einfriedung des Friedhofs"}, {"kategorie": "", "text": "Im Jahr 1916 wurde der Friedhof aufgrund der wachsenden Zahl der Bestattungen erweitert, 1928 wurde ein Aufbahrungsraum geschaffen, der nach dem Zweiten Weltkrieg zwischen 1945 und 1951 instand gesetzt wurde"}, {"kategorie": "", "text": "Der Friedhof war, wie viele andere Wiener Friedhöfe, von der geplanten Schließung im Jahr 1975 betroffen, doch nach einer Volksbefragung 1980 wurde der Schließungsbeschluss aufgehoben, und der Friedhof konnte weiter bestehen."}]'::jsonb, ''),
  ('hittlduafa-friidhof', 'Hittlduafa Friidhof', '', '', '', '', 'Hütteldorfer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 47.714 Quadratmetern und rund 4.600 Grabstellen ist er einer der größeren Friedhöfe in der Region"}, {"kategorie": "", "text": "Der Friedhof, der ab 1811 belegt wurde, ersetzt den alten Hütteldorfer Friedhof, der an der Ecke [[Stockhammerngasse]] und [[Bergmillergasse]] lag und aufgrund von Platzmangel geschlossen wurde"}, {"kategorie": "", "text": "Der Hütteldorfer Friedhof wurde am Ortsende von Hütteldorf angelegt und ab 1811 für Bestattungen genutzt"}, {"kategorie": "", "text": "Eine Besonderheit in der Geschichte des Hütteldorfer Friedhofs war der Plan, einen Waldfriedhof nach deutschem Vorbild im Gemeindewald von [[Hütteldorf]] zu errichten. Dieser Plan wurde 1907 genehmigt, doch stattdessen entstand auf dem vorgesehenen Gelände ab 1919 eine Siedlung"}, {"kategorie": "", "text": "Der heutige Hütteldorfer Friedhof besteht aus zwei Teilen: (i) Alter Teil: Dieser Teil des Friedhofs hat einen malerischen Charakter mit vielen Bäumen und klassizistischen Gräbern, die dem Friedhof ein geschlossenes, historisches Ambiente verleihen. Er erinnert an einen typischen alten Dorffriedhof und bietet eine ruhige, abgeschiedene Atmosphäre;  (ii) Der neuere Bereich des Friedhofs wurde als Parkfriedhof gestaltet, mit vielen Hecken und Büschen, die für ein modernes, gepflegtes Erscheinungsbild sorgen. Dieser Teil des Friedhofs wurde mehrmals erweitert und bietet Raum für neue Bestattungen"}, {"kategorie": "", "text": "In der Nähe der Aufbahrungshalle befindet sich ein besonders gestalteter Gräberhain, in dem Grabsteine aus dem Biedermeier aufgestellt wurden. Diese Gräber stammen ursprünglich aus anderen Friedhöfen und wurden hier als historisches Denkmal erhalten"}, {"kategorie": "", "text": "1953 wurde auf dem Hütteldorfer Friedhof ein Friedhofskreuz errichtet, das bis heute eines der zentralen Denkmäler des Friedhofs ist"}, {"kategorie": "", "text": "Die Aufbahrungshalle wurde 1967 nach den Plänen von Erich Boltenstern erneuert. Die Umgestaltung von 1973/1974 beinhaltete die künstlerische Gestaltung der Apsis durch den Maler Hans Robert Pippal und Glas-Beton-Fenster von Hermann Bauch"}, {"kategorie": "", "text": "Die Mischung aus historischer und moderner Friedhofsgestaltung sowie die künstlerischen Elemente machen den Hütteldorfer Friedhof zu einem bemerkenswerten Ort des Gedenkens."}]'::jsonb, ''),
  ('inzasduafa-friidhof', 'Inzasduafa Friidhof', '', '', '', '', 'Inzersdorfer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 78.864 Quadratmetern und rund 11.300 Grabstellen ist er einer der größeren Friedhöfe und hat eine lange Geschichte, die bis ins 18. Jahrhundert zurückreicht"}, {"kategorie": "", "text": "Der Inzersdorfer Friedhof wurde im Jahr 1784 angelegt, nachdem der alte Friedhof neben der Kirche in der Draschestraße 105 aufgelassen werden musste. In den Jahren 1863, 1875, 1886, 1897, 1912, 1928, 1953, 1975, 1977 und 1979 wurde der Friedhof mehrfach erweitert, um den wachsenden Bedarf zu decken"}, {"kategorie": "", "text": "Im Jahr 1877 wurde eine Kapelle mit Totenkammer sowie eine Totengräberwohnung und eine Friedhofskanzlei errichtet. 1887 folgte der Bau einer neuen Friedhofskapelle"}, {"kategorie": "", "text": "1928 wurde eine Aufbahrungshalle, ein Verwaltungsgebäude sowie eine arkadenähnliche Urnenmauer mit 132 Wandnischen und ein Urnenhain für 850 Urnengrabstellen angelegt. Die Aufbahrungshalle wurde zwischen 1973 und 1974 vom Architekten Erich Boltenstern umgebaut und erhielt einen Flügelaltar von Hans Robert Pippal. Diese Halle wurde 1989 renoviert"}, {"kategorie": "", "text": "Ein weiteres bedeutendes Bauwerk auf dem Friedhof ist das Drasche-Mausoleum, auch bekannt als Gruftkapelle der Familie Drasche, das 1892 von Alexander von Wielemans für Dr. Richard Drasche Ritter von Wartinberg errichtet wurde. Dieses Mausoleum wurde 1962 umfassend instand gesetzt. Die Familie Drasche spielte eine bedeutende Rolle in der Entwicklung [[Inzersdorfs]], und ihre Grabstätte zählt zu den künstlerischen und historischen Höhepunkten des Friedhofs"}, {"kategorie": "", "text": "Auf dem Inzersdorfer Friedhof befinden sich auch zahlreiche sowjetische Kriegsgräber, die an die gefallenen Soldaten der Roten Armee während des Zweiten Weltkriegs erinnern. Diese Gräber sind ein wichtiges Denkmal für die Opfer des Krieges und fügen dem Friedhof eine historische Dimension hinzu"}, {"kategorie": "", "text": "Mit seinen 11.300 Grabstellen, der Friedhofskapelle, dem Drasche-Mausoleum und den sowjetischen Kriegsgräbern ist der Inzersdorfer Friedhof ein historischer Ort, der das kulturelle und historische Erbe der Region widerspiegelt."}]'::jsonb, ''),
  ('kagrana-friidhof', 'Kagrana Friidhof', '', '', '', '', 'Kagraner Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 56.618 Quadratmetern sowie etwa 7.600 Grabstellen ist der Kagraner Friedhof eine der größeren Begräbnisstätten der Region"}, {"kategorie": "", "text": "Er wurde im späten 19. Jahrhundert als neuer Ortsfriedhof von Kagran errichtet und weist eine lange Geschichte von Erweiterungen und architektonischen Entwicklungen auf"}, {"kategorie": "", "text": "Der Kagraner Friedhof kombiniert traditionelle Friedhofsarchitektur mit moderner Gestaltung. Er beherbergt historische Denkmäler (wie Glockenturm und Kapellen, sowie das von Barbara Schmeykal gestiftete Gedächtniskreuz und das von Pfarrer Andreas Huger gewidmete Steinerne Kreuz) und verbindet diese mit modernen Elementen wie dem Urnenhain (Gruppe 15) und der Aufbahrungshalle von 1966, die durch ihre künstlerische Gestaltung hervorsticht."}]'::jsonb, ''),
  ('kaisaebaschduafa-friidhof', 'Kaisaebaschduafa Friidhof', '', '', '', '', 'Kaiserebersdorfer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 12.060 Quadratmetern und rund 1.200 Grabstellen ist er ein vergleichsweise kleiner Friedhof"}, {"kategorie": "", "text": "Bereits am 15. Jänner 1681 wird der Friedhof am heutigen Standort erwähnt, und er blieb von den Friedhofsschließungen unter Joseph II. verschont. Während der Choleraepidemie 1866 wurden die Toten am heutigen Zehngrafweg bestattet, und ab 1877 wurde der Ortsfriedhof mehrmals erweitert"}, {"kategorie": "", "text": "Eine geplante Schließung des Friedhofs im Jahr 1985 wurde nach einer Entscheidung des Wiener Gemeinderats 1980 aufgehoben. In den folgenden Jahren konnten in den ehemals als Sperrfriedhöfe vorgesehenen Friedhöfen wieder Grabstellen vergeben werden"}, {"kategorie": "", "text": "Hinter dem schönen Backsteineingang des Friedhofs befinden sich Grabsteine aus der Mitte des 19. Jahrhunderts, die das historische Erbe der Region repräsentieren"}, {"kategorie": "", "text": "Ein besonderes Merkmal des Friedhofs ist das Kriegerdenkmal, das den Opfern der Kriege gewidmet ist"}, {"kategorie": "", "text": "Die umfangreichen Renovierungen in den 1980er Jahren haben den Friedhof modernisiert und zu einem gepflegten Ort der Ruhe und des Gedenkens gemacht."}]'::jsonb, ''),
  ('pfoakiachn-kaisaebaschduaf', 'Pfoakiachn Kaisaebaschduaf', '', '', '', '', 'Pfarrkirche Kaiserebersdorf', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 11. Wiener Gemeindebezirk ([[Simmering]]), im Stadtteil [[Kaiserebersdorf]]\""}, {"kategorie": "", "text": "Sie ist dem Heiligen Petrus und Paulus geweiht und wurde erstmals im Jahr 1429 urkundlich erwähnt, was sie zu einer der ältesten Sakralbauten in der Region macht"}, {"kategorie": "", "text": "Ursprünglich diente sie als eine Wehrkirche und war Teil der mittelalterlichen Dorfbefestigung von Kaiserebersdorf, das damals ein eigenständiger Ort war"}, {"kategorie": "", "text": "Besonders erwähnenswert ist die Barockisierung der Kirche im 17. und 18. Jahrhundert, die der Kirche ihr heutiges Aussehen verlieh. Der Kirchenbau besteht aus einem rechteckigen Langhaus mit einem wuchtigen Kirchturm, der weithin sichtbar ist und dem Sakralbau ein markantes Profil verleiht"}, {"kategorie": "", "text": "Die Pfarrkirche Kaiserebersdorf weist stilistische Elemente verschiedener Epochen auf, wobei die Barockzeit besonders hervorzuheben ist. Im Innenraum der Kirche befinden sich zahlreiche barocke Kunstwerke, darunter der Hochaltar, der den Heiligen Petrus und Paulus gewidmet ist. Der schlichte, aber ehrwürdige Stil des Kirchenschiffs und die religiösen Darstellungen machen die Kirche zu einem bedeutenden Denkmal der Wiener Kirchenarchitektur."}]'::jsonb, ''),
  ('schloss-kaisaebaschduaf', 'Schloss Kaisaebaschduaf', '', '', '', '', 'Schloss Kaiserebersdorf', '[{"kategorie": "", "text": "Das Bauwerk hat eine lange, wechselvolle Geschichte. Ursprünglich ein fürstliches Jagdschloss, diente es im Laufe der Jahrhunderte verschiedenen Zwecken, von einer königlichen Residenz über ein Armenhaus bis hin zu einer Strafanstalt"}, {"kategorie": "", "text": "Das Schloss geht auf das Jahr 1499 zurück, als die Herrschaft Ebersdorf an [[Maximilian]] I. überging, woraufhin der Ort in [[Kaiserebersdorf]] umbenannt wurde. Maximilian I. ließ das Schloss als fürstliches Jagdschloss umgestalten"}, {"kategorie": "", "text": "Zwischen 1558 und 1561 wurde das Schloss weiter ausgebaut. Es erhielt eine Aufstockung, zwei neue Flügel, ein Vorwerk und einen Wassergraben. In der Folge ließ [[Ferdinand]] II. das Schloss renovieren, welches in dieser Zeit eine neue Blüte erlebte"}, {"kategorie": "", "text": "Während der [[Zweiten]] Türkenbelagerung im Jahr 1683 wurde das Schloss schwer beschädigt, jedoch bald nach den Plänen des Architekten Lodovico Ottavio Burnacini wiederhergestellt. Das kaiserliche Wappen, das heute noch am Torbogen zu sehen ist, stammt aus dieser Zeit"}, {"kategorie": "", "text": "Im 18. Jahrhundert nahm die Bedeutung des Schlosses allmählich ab. Maria Theresia schenkte das Schloss am 3. September 1745 dem Domscholaster und Pfarrer von Kaiserebersdorf, dem späteren Weihbischof Anton von Marxer, um es in ein Armen- und Versorgungshaus umzuwandeln. Ab 1773 wurde das Schloss in eine Artilleriekaserne umfunktioniert, und 1868 diente es als Infanteriekaserne"}, {"kategorie": "", "text": "Ab 1883 befand sich im Schloss das Monturdepot der Hoch- und Deutschmeister, bevor es 1920 in eine Jugendstrafanstalt und schließlich 1975 in eine Strafvollzugsanstalt umgewandelt wurde, eine Funktion, die das Schloss bis heute erfüllt"}, {"kategorie": "", "text": "Das Schloss Kaiserebersdorf wurde mehrmals restauriert und umgebaut, um den wechselnden Anforderungen gerecht zu werden. Besonders bemerkenswert sind die barocken Elemente, die von Lodovico Ottavio Burnacini nach der Zerstörung durch die Türken hinzugefügt wurden. Der imposante Torbogen mit dem kaiserlichen Wappen zeugt noch heute von der einstigen Bedeutung des Schlosses."}]'::jsonb, ''),
  ('lainza-friidhof', 'Lainza Friidhof', '', '', '', '', 'Lainzer Friedhof', '[{"kategorie": "", "text": "Er wurde im Jahr 1876 als gemeinsamer Friedhof für die Ortschaften [[Lainz]] und [[Speising]] eröffnet"}, {"kategorie": "", "text": "Der Friedhof erstreckt sich über eine Fläche von 7.248 Quadratmetern und umfasst rund 900 Grabstellen. Er liegt auf dem Rücken des Stranzenbergs, nahe dem [[Küniglberg]]"}, {"kategorie": "", "text": "Der Lainzer Friedhof weist eine interessante Mischung von Grüften aus dem Fin de Siècle und neueren Gräbern auf. Die architektonischen Ergänzungen aus den 1930er Jahren, insbesondere die vom Architekten Karl Ehn 1936 gebaute Aufbahrungshalle, der Glockenraum und die Beisetzkammer, prägen das Erscheinungsbild des Friedhofs. Karl Ehn selbst ist auch auf dem Lainzer Friedhof begraben (Gruppe 3, Nummer 162)"}, {"kategorie": "", "text": "Trotz mehrerer geplanter Schließungen konnte der Friedhof seine Funktion bis heute beibehalten."}]'::jsonb, ''),
  ('leopoidaua-friidhof', 'Leopoidaua Friidhof', '', '', '', '', 'Leopoldauer Friedhof', '[{"kategorie": "", "text": "Mit einer Fläche von 4.949 Quadratmetern und rund 650 Grabstellen ist er ein vergleichsweise kleiner Friedhof. Der Friedhof ist eng mit der Geschichte der Pfarrkirche Leopoldau verbunden und stellt eines der wenigen erhaltenen Kirchhöfe im Wiener Stadtgebiet dar"}, {"kategorie": "", "text": "Der ursprüngliche Leopoldauer Friedhof wurde bereits um 1489 angelegt, als das Gebiet zur Pfarre erhoben wurde. Er befand sich ursprünglich direkt um die [[Pfarrkirche]] Leopoldau"}, {"kategorie": "", "text": "Im Jahr 1872 wurde ein neuer Friedhofsteil eröffnet und am 11. August 1872 geweiht. In dieser Zeit diente der Friedhof der Bestattung der katholischen Verstorbenen aus dem ehemals eigenständigen Vorort Leopoldau, der 1905 nach Wien eingemeindet wurde"}, {"kategorie": "", "text": "Weitere Erweiterungen folgten in den Jahren 1906 und 1910, und der Friedhof wurde 1910 mit einer Mauer umgeben. Am 12. März 1945 erlitt der Leopoldauer Friedhof schwere Schäden durch einen Luftangriff, bei dem acht Bomben einschlugen und zahlreiche Grabstätten zerstört wurden"}, {"kategorie": "", "text": "In den 1950er Jahren gehörte der Leopoldauer Friedhof zu den Friedhöfen, die gemäß einem Beschluss des Wiener Gemeinderats bis 1975 geschlossen werden sollten. Obwohl die Sperre verlängert wurde, wurde sie nach einer Volksbefragung im Jahr 1980 endgültig aufgehoben, sodass der Friedhof weiterhin genutzt werden konnte"}, {"kategorie": "", "text": "Da der Leopoldauer Friedhof keine eigene Aufbahrungshalle besaß, wurden Verstorbene bis 1945 in ihren Wohnhäusern aufgebahrt. Nach 1945 wurde dies verboten, und seither werden Verstorbene in der Pfarrkirche Leopoldau aufgebahrt. Angehörige anderer christlicher Konfessionen werden seit 1982 ebenfalls in der Kirche aufgebahrt"}, {"kategorie": "", "text": "Der Leopoldauer Friedhof zeichnet sich durch seinen ländlichen Charakter aus, der besonders durch die zahlreichen schmiedeeisernen Kreuze betont wird. Dieser Friedhof gehört zu den wenigen noch erhaltenen Kirchhöfen in Wien und bildet zusammen mit der [[Pfarrkirche]] Leopoldau ein sehenswertes Ensemble."}]'::jsonb, ''),
  ('friidhof-maua', 'Friidhof Maua', '', '', '', '', 'Friedhof Mauer', '[{"kategorie": "", "text": "Der Friedhof wurde im Jahr 1867 von der damals eigenständigen Gemeinde [[Mauer]] auf dem Reiterberg errichtet. Mit einer Fläche von 48.337 Quadratmetern und rund 5.500 Grabstellen ist er einer der größeren Friedhöfe in diesem Bezirk"}, {"kategorie": "", "text": "Der Maurer Friedhof entstand, nachdem das k. k. Bezirksamt Hietzing 1867 die Erweiterung des bisherigen Friedhofs in Mauer abgelehnt hatte. Die Weihe des neuen Friedhofs fand am 30. Dezember 1867 statt. Der Friedhof wurde mehrfach erweitert: zunächst 1876, dann 1888 und erneut 1925. Im Laufe seiner Geschichte wurde der Friedhof mehrfach vergrößert, zuletzt im Jahr 1949"}, {"kategorie": "", "text": "Der Maurer Friedhof ist nicht nur eine Begräbnisstätte, sondern auch ein bedeutendes kunsthistorisches Denkmal. Er beherbergt mehrere der kunstvollsten und historisch bedeutsamsten Mausoleen Wiens. Zu den bekanntesten gehören: (i) die neugotische Kapelle der Familien Alber-Justus und Ölzelt; (ii) das backsteingotische Mausoleum der Familie Katlein; (iii) die Mausoleen der Familien Knips-Krasse und Salcher, die im klassizistischen Stil errichtet wurden, sowie (iv) die neobarocke Kapelle der Familie Mallmann"}, {"kategorie": "", "text": "Zusätzlich gibt es mehrere Jugendstil-Grüfte, die den Friedhof kunsthistorisch bereichern. Der Urnenhain ist kreisförmig angelegt und verleiht der Anlage eine besondere architektonische Struktur. Bemerkenswert ist auch die moderne Aufbahrungshalle mit ihren markanten Spitzarkaden, die eine ästhetische Verbindung von Tradition und Moderne darstellt"}, {"kategorie": "", "text": "Neben den kunstvollen Mausoleen verfügt der Friedhof über ein Kriegsgrab für die Opfer des Ersten Weltkriegs, das eine zentrale Gedenkstätte für die gefallenen Soldaten darstellt. Dieser historische Aspekt unterstreicht die Bedeutung des Maurer Friedhofs sowohl als Ort der letzten Ruhe als auch als Mahnmal."}]'::jsonb, ''),
  ('obalaara-friidhof', 'Obalaara Friidhof', '', '', '', '', 'Oberlaaer Friedhof', '[{"kategorie": "", "text": "Er erstreckt sich über eine Fläche von 34.514 Quadratmetern und ist mit rund 4.700 Grabstellen ein bedeutender Friedhof für die Region [[Oberlaa]], [[Rothneusiedl]] und [[Unterlaa]], der durch mehrere Erweiterungen und Umbauten den Bedürfnissen der Region angepasst wurde"}, {"kategorie": "", "text": "Bereits im Mittelalter existierte ein Friedhof um die Kirche von Oberlaa.  1832 folgte die Auflassung des hinteren Friedhofsteils bei der Kirche. Ein neuer Friedhofsteil wurde mit der Genehmigung von 1831 hinter dem alten Friedhof angelegt und am 7. September 1833 geweiht. Erweiterungen des Friedhofs fanden in den Jahren 1851, 1885 und 1889 statt"}, {"kategorie": "", "text": "1889 wurde eine neue Totenkammer mit Sezierkammer erbaut, die 1940 umgestaltet wurde, wobei ein Aufbahrungsraum, eine Beisetzkammer und ein Werkzeugraum hinzukamen"}, {"kategorie": "", "text": "1966 wurde die alte Aufbahrungshalle abgerissen und nach den Plänen des Architekten Josef Strelec ein Neubau errichtet. Die Innenausstattung erfolgte durch Erich Boltenstern, der unter anderem das Altarmosaik und das Altarkreuz entwarf. Der Künstler Hermann Bauch schuf ein dreiteiliges Bleiglasfenster. Der Betrieb der neuen Aufbahrungshalle begann am 11. Dezember 1967"}, {"kategorie": "", "text": "Neben den typischen Familiengrüften aus der Zeit um die Jahrhundertwende und einigen älteren Gräbern aus der zweiten Hälfte des 19. Jahrhunderts ist insbesondere das Mausoleum der Familie Zwicklsdorfer aus dem Jahr 1855 von besonderem Interesse"}, {"kategorie": "", "text": "Der Oberlaaer Friedhof zeichnet sich durch seine geschichtliche Bedeutung und die kunstvolle Gestaltung seiner Bauten aus, insbesondere durch die moderne Aufbahrungshalle und die historischen Gräber und Mausoleen."}]'::jsonb, ''),
  ('friidhof-oba-sankt-veit', 'Friidhof Oba Sankt Veit', '', '', '', '', 'Friedhof Ober-Sankt-Veit', '[{"kategorie": "", "text": "Der Friedhof erstreckt sich über eine Fläche von 35.934 Quadratmetern und behrebergt rund 4.600 Grabstellen. Er gehört zum Typus der Park- und Bergfriedhöfe, was ihm durch seine hügelige Lage und seine parkähnliche Gestaltung eine besondere Atmosphäre verleiht."}, {"kategorie": "", "text": "Der ursprüngliche Friedhof von Ober-Sankt-Veit, der sich im Bereich des heutigen Streckerparks (zwischen [[Rohrbacherstraße]], [[Streckerplatz]] und [[Auhofstraße]]) befand, wurde im Laufe der Zeit zu klein. Daraufhin errichtete die Gemeinde Ober-Sankt-Veit im Jahr 1876 einen neuen Friedhof in der Gemeindeberggasse. Die Weihe des neuen Friedhofs fand am 2. November 1876 statt, woran eine Gedenktafel beim Friedhofskreuz erinnert"}, {"kategorie": "", "text": "Im Laufe der Jahre wurde der Friedhof mehrfach erweitert, um den steigenden Bestattungsbedarf zu decken. In den Jahren 1964 bis 1966 wurde die Aufbahrungshalle nach den Plänen des Architekten Erich Boltenstern umgestaltet, und die künstlerische Ausgestaltung übernahm der Maler Hermann Bauch"}, {"kategorie": "", "text": "Der Ober-St.-Veiter Friedhof beherbergt zahlreiche prachtvolle Mausoleen, die vor allem im oberen Teil des Friedhofs zu finden sind. Besonders eindrucksvoll sind die Mausoleen der Familie Flesch und der Familie Schmiedleitner, die in ihrer Größe beinahe das Ausmaß einer mittelgroßen Kirche erreichen"}, {"kategorie": "", "text": "In der Nähe des Eingangs findet man das schlichte Grab des berühmten österreichischen Künstlers Egon Schiele und seiner Frau Edith Schiele, die beide im Jahr 1918 an der Spanischen Grippe starben. Auch das Grab von Franz Ritter von Jauner (Schauspieler und Theaterdirektor, 1831-1900) befindet sich auf dem Ober-Sankt-Veiter Friedhof"}, {"kategorie": "", "text": "Abgegrenzt sind zudem die Ruhestätten verschiedener Ordensgemeinschaften, darunter die Dominikanerinnen in Wien-Hacking, die Kongregation der Dienerinnen des Heiligsten Herzens Jesu, die Barmherzigen Schwestern und der Karmeliterorden."}]'::jsonb, ''),
  ('oba-sankt-veita-kiachn', 'Oba-Sankt-Veita-Kiachn', '', '', '', '', 'Ober-Sankt-Veiter-Kirche', '[{"kategorie": "", "text": "Die Pfarrkirche Ober-Sankt-Veit ist dem Heiligen Vitus (Veit) geweiht, einem frühchristlichen Märtyrer, der in Österreich, besonders in Ober-Sankt-Veit, eine besondere Verehrung genießt. Zusätzlich ist die Kirche auch der Maria, Zuflucht der Sünder geweiht, was ihre marianische Tradition betont"}, {"kategorie": "", "text": "Die Kirche wurde bereits 1260 und 1298 urkundlich als Pfarrkirche erwähnt und gelangte 1365 in den Besitz der Dompropstei St. Stephan. Ursprünglich war sie Teil einer Wehrkirche, erkennbar an der erhaltenen geböschten gotischen Stützmauer"}, {"kategorie": "", "text": "Während der [[Türkenbelagerungen]] wurde die Kirche zweimal zerstört: 1529 und erneut 1683. Der Wiederaufbau nach 1683 führte unter der Leitung von Matthias Gerl im barocken Stil zu einem weiteren Neubau, der 1745 geweiht wurde. Teile des ursprünglichen Chors und der Krypta blieben erhalten"}, {"kategorie": "", "text": "Der Hochaltar stammt aus dem Jahr 1745 und zeigt das Gemälde Martyrium des Heiligen Veit, ein Werk von Fra Agostino a San Luca. Weitere bedeutende Kunstwerke sind die Seitenaltarbilder „Himmelfahrt Mariae“ und „Glorie des Heiligen Josef“ von Gaetano de Rosa sowie das Gemälde „Heilige Anna lehrt Maria das Lesen“ von Franz Anton Tschungko. Die Orgel wurde 1932 von der Firma Johann M. Kauffmann gefertigt"}, {"kategorie": "", "text": "1994 wurde nach den Plänen des Architekten Hermann Bauer eine neue Taufkapelle errichtet, die auch als Werktagskirche genutzt wird. Der Kapellenboden besteht aus griechischem Marmor, der Altar und der Ambo wurden aus Wachauer Marmor gestaltet und zeigen kunstvolle Reliefs. Die Gestaltung stammt vom Künstler Peter Niedertscheider"}, {"kategorie": "", "text": "Die Pfarrkirche Ober-Sankt-Veit ist ein bedeutendes historisches und religiöses Zentrum in Hietzing. Sie ist mit dem benachbarten Erzbischöflichen Schloss baulich verbunden und steht heute unter Denkmalschutz"}]'::jsonb, ''),
  ('kardinal-koenig-plotz', 'Kardinal-König-Plotz', '', '', '', '', 'Kardinal-König-Platz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Stadtteil [[Lainz]]\""}, {"kategorie": "", "text": "Der Platz wurde nach Franz Kardinal König (1905–2004) benannt, einem einflussreichen österreichischen Kardinal und ehemaligen Erzbischof von Wien. Er spielte eine zentrale Rolle in der katholischen Kirche des 20. Jahrhunderts und war bekannt für seine Bemühungen um den interreligiösen Dialog und die Ökumene"}, {"kategorie": "", "text": "Der Kardinal-König-Platz ist ein wichtiger Knotenpunkt und liegt vor der [[Konzilsgedächtniskirche]] der Pfarre [[Lainz]]. Die Kirche bildet das geistliche Zentrum des Platzes und ist ein bedeutendes religiöses und architektonisches Wahrzeichen des Bezirks"}, {"kategorie": "", "text": "Der Platz verbindet die [[Jagdschlossgasse]] und die [[Lainzer]] Straße, zwei zentrale Verkehrswege in Hietzing. Rund um den Platz befinden sich weitere historische Gebäude und Einrichtungen, die zum kulturellen Erbe der Region beitragen."}]'::jsonb, ''),
  ('kardinal-koenig-haus', 'Kardinal-König-Haus', '', '', '', '', 'Kardinal-König-Haus', '[{"kategorie": "allg.", "text": "\"bedeutendes Zentrum für spirituelle Bildung und soziale Anliegen  im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Stadtteil [[Lainz]] am Kardinal-König-Platz\""}, {"kategorie": "", "text": "Es ist ein Bildungs- und Exerzitienzentrum, das von den Jesuiten und der Caritas betrieben wird"}, {"kategorie": "", "text": "Benannt ist es nach Franz Kardinal König (1905–2004), einem einflussreichen österreichischen Kardinal und ehemaligen Erzbischof von Wien, der eine zentrale Rolle in der katholischen Kirche des 20. Jahrhunderts spielte und für seine Bemühungen um den interreligiösen Dialog und die Ökumene bekannt war"}, {"kategorie": "", "text": "Das Haus steht in enger Verbindung zur benachbarten [[Konzilsgedächtniskirche]], die ebenfalls von den Jesuiten betreut wird. Gemeinsam bilden die Einrichtungen ein spirituelles und kulturelles Zentrum in [[Lainz]]."}]'::jsonb, ''),
  ('wueuede-siidlungen', 'Wüüde Siidlungen', '', '', '', '', 'Wilde Siedlungen', '[{"kategorie": "allg.", "text": "\"Nach 1918 ein verbreitetes Phänomen in Wien, bei dem illegale Siedlungen entstanden, oft verbunden mit gärtnerischer Nutzung\""}, {"kategorie": "", "text": "Ursachen waren die Wohnungsnot, Nahrungsmittelknappheit, Arbeitslosigkeit und der Mangel an Brennholz nach dem [[Ersten]] Weltkrieg"}, {"kategorie": "", "text": "Der Wiener Magistrat war der schnellen Ausbreitung dieser Siedlungen auf Stadtrandflächen kaum gewachsen, weshalb sie erst nachträglich erfasst wurden. Ab 1921 wurden einige der wilden Siedlungen in genossenschaftliche Siedlungsbewegungen integriert, und die Stadt Wien schuf 1929 spezielle Zonen für deren Konsolidierung"}, {"kategorie": "", "text": "Ein weiterer Schub wilder Siedlungen trat während der Weltwirtschaftskrise der 1930er Jahre und erneut nach dem [[Zweiten]] Weltkrieg auf. In den 1950er Jahren wurden viele Siedlungen nachträglich mit Infrastruktur ausgestattet und legalisiert, dennoch zogen sich baurechtliche Maßnahmen zur Genehmigung bis in die jüngere Vergangenheit hin"}, {"kategorie": "", "text": "Die „wilden“ Siedlungen unterschieden sich in ihrer Entstehung und Form. Es gab Ackersiedlungen, die auf parzelliertem Ackerland entstanden, sowie Rodungssiedlungen, die durch illegale Rodungen im Wienerwald und in den Donauauen angelegt wurden. Manche dieser Siedlungen wurden später in Kleingartensiedlungen umgewandelt"}, {"kategorie": "", "text": "Wild entstandene Siedlungen existierten auf Brachflächen, Bahnanlagen oder ehemaligen Industriegebieten wie Ziegeleien und Kiesgruben. Trotz des offiziellen Widerstands prägten diese Siedlungen das Stadtbild und sind auch heute noch ein bedeutender Teil des Wiener Siedlungskörpers"}, {"kategorie": "", "text": "Die Siedlung [[Bruckhaufen]] entstand auf einer Schutt- und Müllhalde, um den Ortskern von [[Leopoldau]] wurden aufgelassene Kiesgruben besiedelt. Im Süden Wiens finden sich in Kleingartenanlagen umgewandelte ehemalige Ziegeleien (nördlich des heutigen [[Laaer]] Walds, am Schwimmschulteich, am Steinsee oder am Schellensee)."}]'::jsonb, ''),
  ('aum-freihof', 'Aum Freihof', '', '', '', '', 'Am Freihof', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 22. Wiener Gemeindebezirk ([[Donaustadt]]) im Stadtteil [[Kagran]]\""}, {"kategorie": "", "text": "Die Straße ist nach dem historischen Freihof benannt - einem Gutshof, der erstmals 1650 urkundlich erwähnt wurde"}, {"kategorie": "", "text": "Der Freihof war ein abgabenfreier landwirtschaftlicher Betrieb in Kagran - ein Privileg, das ihm eine besondere Stellung in der lokalen Wirtschaft und Verwaltung verlieh. Über Jahrhunderte war der Freihof ein zentrales Anwesen in Kagran und diente sowohl landwirtschaftlichen als auch wirtschaftlichen Zwecken"}, {"kategorie": "", "text": "Die Straße befindet sich in einem Gebiet, das in den 1920er Jahren im Zuge der Entwicklung der [[Freihofsiedlung]] urbanisiert wurde. Die Freihofsiedlung selbst wurde in den 1920er Jahren als Gartenstadt und Wohnsiedlung vorwiegend für Angestellte der städtischen Versorgungsbetriebe (wie Elektrizitäts- und Gaswerke) errichtet"}, {"kategorie": "", "text": "Die Siedlung und die Straße stehen somit in engem historischen Zusammenhang mit der Entwicklung des Bezirks als Wohngebiet. Heute ist die Straße \"Am Freihof\" Teil eines ruhigen und gut erschlossenen Wohngebiets, das sich durch seine gartenstadtartige Bebauung auszeichnet."}]'::jsonb, ''),
  ('kagrana-aunga', 'Kagrana Aunga', '', '', '', '', 'Kagraner Anger', '[{"kategorie": "allg.", "text": "\"Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]]) im Stadtteil Kagran\""}, {"kategorie": "", "text": "Ursprünglich handelte es sich um eine freie, unbebaute Fläche, wobei der Begriff \"Anger\" für \"Kagraner Gemeindeanger\" steht - eine gemeinschaftlich genutzte Grünfläche, die häufig als Viehweide, Marktplatz oder zentraler Treffpunkt diente"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wurde das Gebiet um den Kagraner Anger urbanisiert und in die wachsende Stadt Wien integriert. Heute ist der Kagraner Anger von Wohnbauten und modernen Einrichtungen umgeben, behält aber durch die angrenzenden Grünflächen und historischen Bezüge einen gewissen dörflichen Charakter"}, {"kategorie": "", "text": "Die Straße verläuft an der Grenze zur [[Freihofsiedlung]], die durch eine Mischung aus Siedlungsbauten, öffentlichen Einrichtungen und Grünanlagen geprägt ist und weiterhin eine wichtige Rolle im städtischen Leben des Bezirks Donaustadt spielt"}, {"kategorie": "", "text": "Die Straße \"Kagraner Anger\" erinnert somit an die dörfliche Vergangenheit Kagrans, das sich von einem landwirtschaftlich geprägten Dorf zu einem Teil des modernen Stadtbezirks entwickelt hat."}]'::jsonb, '')
